const grid=document.getElementById("courseGrid"),dlg=document.getElementById("courseDialog");
courses.forEach(c=>{const card=document.createElement("article");card.className="course";card.innerHTML='<span class="tag"></span><h3></h3><p></p><p class="module-count"></p><button class="btn secondary">View CMCE subjects</button>';card.querySelector(".tag").textContent=c.code;card.querySelector("h3").textContent=c.name;card.querySelector("p").textContent=c.desc;card.querySelector(".module-count").textContent=c.modules.length+" CMCE examination subjects";card.querySelector("button").addEventListener("click",()=>{document.getElementById("dialogTitle").textContent=c.name;document.getElementById("dialogDesc").textContent=c.desc;document.getElementById("moduleCount").textContent=c.modules.length+" examination subjects";const mg=document.getElementById("moduleGrid");mg.replaceChildren();document.getElementById("moduleWorkspace").hidden=true;document.getElementById("moduleGrid").hidden=false;document.getElementById("quizPanel").hidden=true;c.modules.forEach((m,i)=>{const item=document.createElement("article");item.className="module-card";const h=document.createElement("h4");h.textContent=(i+1)+". "+m;const p=document.createElement("p");p.textContent="Preview, platform test and premium practice";const b=document.createElement("button");b.type="button";b.className="module-open-btn";b.textContent="Open module dashboard →";const openDashboard=()=>{selectedCourse=c;selectedModuleIndex=i;document.getElementById("selectedModuleTitle").textContent=m;document.getElementById("moduleGrid").hidden=true;document.getElementById("moduleWorkspace").hidden=false;document.getElementById("workspaceHome").hidden=false;["previewPage","premiumPage","testPage"].forEach(id=>document.getElementById(id).hidden=true);document.getElementById("cppPremiumControls").hidden=!(c.code==="PGCP-AC"&&(i===0||i===1||i===2||i===3||i===4)||c.code==="PGCP-MC"&&(i===0||i===1||i===2||i===3||i===4)||c.code==="PGCP-VLSI"&&(i===0||i===1||i===2||i===3||i===4)||c.code==="PGCP-ESD"&&(i===0||i===1));document.getElementById("cppPremiumLevel").value="easy";Array.from(document.getElementById("cppPremiumLevel").options).forEach(o=>{o.disabled=false;});document.getElementById("premiumUnavailable").hidden=(c.code==="PGCP-AC"&&(i===0||i===1||i===2||i===3||i===4)||c.code==="PGCP-MC"&&(i===0||i===1||i===2||i===3||i===4)||c.code==="PGCP-VLSI"&&(i===0||i===1||i===2||i===3||i===4)||c.code==="PGCP-ESD"&&(i===0||i===1));document.getElementById("premiumPracticePanel").hidden=true;document.getElementById("testIntro").hidden=false;document.getElementById("examInterface").hidden=true;document.getElementById("examResult").hidden=true;activeQs=c.code==="PGCP-MC"?(i===0?osLinuxQs:i===1?dbQs:i===2?mcJavaQs:i===3?mcDsaQs:mcWebJavaQs):c.code==="PGCP-BDA"?(i===0?bdaLinuxCloudQs:i===1?bdaPythonRQs:i===2?bdaJavaQs:bdaBigDataQs):c.code==="PGCP-AI"?(i===0?aiFundamentalsQs:i===1?aiAdvancedProgrammingQs:i===2?aiDataAnalyticsQs:aiPracticalMLQs):c.code==="PGCP-ESD"?(i===0?esdEmbeddedCQs:i===1?esdDsaQs:i===2?esdMcuQs:esdOsQs):c.code==="PGCP-VLSI"?(i===0?vlsiDigitalQs:i===1?vlsiSystemQs:i===2?vlsiLinuxPythonQs:i===3?vlsiVerilogQs:vlsiSynthesisQs):i===0?cppQs:i===1?javaQs:i===2?dsaQs:i===3?dbQs:webQs;document.getElementById("quizModeLabel").textContent=m+" · 20-question free preview";requestAnimationFrame(()=>{const target=document.getElementById("moduleWorkspace");const dialog=document.getElementById("courseDialog");const top=target.getBoundingClientRect().top-dialog.getBoundingClientRect().top+dialog.scrollTop-18;dialog.scrollTo({top:Math.max(0,top),behavior:"smooth"});});};item.tabIndex=0;item.setAttribute("role","button");item.setAttribute("aria-label","Open "+m+" module dashboard");item.addEventListener("click",openDashboard);item.addEventListener("keydown",e=>{if(e.key==="Enter"||e.key===" "){e.preventDefault();openDashboard()}});b.addEventListener("click",e=>{e.stopPropagation();openDashboard()});item.append(h,p,b);mg.appendChild(item)});dlg.showModal()});grid.appendChild(card)});const cppQs=[
{q:"Which feature of C++ allows functions with the same name to be distinguished by their parameter lists?",o:["Function overloading","Function overriding","Encapsulation","Name hiding"],a:0,e:"Function overloading declares multiple functions with the same name but different parameter lists."},
{q:"What is the result of the expression 17 / 5 when both operands are int?",o:["3.4","3","4","2"],a:1,e:"Integer division discards the fractional part, so 17 / 5 evaluates to 3."},
{q:"Which declaration creates a reference to an existing integer variable x?",o:["int *r = x;","int &r = x;","int r = &x;","ref int r = x;"],a:1,e:"The ampersand in a reference declaration makes r an alias for x; it must be initialized."},
{q:"Which operator accesses a data member through an object pointer p?",o:[".","->","::","&"],a:1,e:"The arrow operator accesses a member through a pointer. p->value is equivalent to (*p).value."},
{q:"Which keyword declares a class-level member shared by all objects of that class?",o:["mutable","virtual","static","inline"],a:2,e:"A static data member belongs to the class, so all objects share the same member."},
{q:"Which access specifier allows a class member to be accessed from any code that can access the object?",o:["private","protected","public","friend"],a:2,e:"Public members can be accessed from outside the class through an accessible object."},
{q:"What is the primary purpose of a constructor in C++?",o:["Destroy an object","Initialize an object","Allocate every pointer automatically","Return an object"],a:1,e:"A constructor initializes an object when it is created and has the same name as its class."},
{q:"Which special member function is called automatically when an object reaches the end of its lifetime?",o:["Constructor","Destructor","Copy assignment operator","Conversion function"],a:1,e:"The destructor performs cleanup when an object's lifetime ends; its name is prefixed with a tilde."},
{q:"Which inheritance relationship allows a derived class to use accessible members of a base class?",o:["Inheritance","Function overloading","Namespace aliasing","Operator precedence"],a:0,e:"Inheritance creates a derived class from a base class and supports reuse and extension of its interface and behavior."},
{q:"What does a virtual function enable when called through a base-class pointer to a derived object?",o:["Compile-time constant folding","Runtime polymorphism","Automatic multiple inheritance","Static data sharing"],a:1,e:"A virtual call is dispatched according to the actual object's type at runtime."},
{q:"Which statement about a const object is correct?",o:["Its non-mutable data members cannot be modified through that object","It cannot be created dynamically","It must have only static members","It cannot call any member function"],a:0,e:"A const object cannot modify its non-mutable state through that object and can call const-qualified member functions."},
{q:"What does the scope resolution operator :: commonly do in C++?",o:["Dereferences a pointer","Accesses a name in a scope such as a class or namespace","Compares two values","Allocates memory"],a:1,e:"The scope resolution operator qualifies a name with its namespace or class scope, and is also used in out-of-class member definitions."},
{q:"Which standard library container provides dynamically resizable sequence storage?",o:["std::vector","std::pair","std::array","std::tuple"],a:0,e:"std::vector is a sequence container that can grow or shrink dynamically."},
{q:"For an array int a[6], what is the index of its last element?",o:["6","5","4","1"],a:1,e:"C++ array indexing starts at zero, so a six-element array has valid indices 0 through 5."},
{q:"Which loop checks its condition before executing its body?",o:["do-while","while","Both while and for","Neither while nor for"],a:2,e:"Both while and for are entry-controlled loops: their condition is checked before each iteration."},
{q:"What is the effect of passing an int parameter by reference using int&?",o:["The function receives an independent copy","The parameter aliases the caller's argument","The argument is always converted to a pointer","The function cannot modify the argument"],a:1,e:"A reference parameter aliases the caller's variable, so changes made through it affect the original argument."},
{q:"Which operator is used to allocate a single object dynamically in C++?",o:["malloc","new","alloc","create"],a:1,e:"The new expression allocates storage and constructs an object, returning a pointer to it."},
{q:"Which operator should normally be paired with new for a single dynamically allocated object?",o:["free","delete[]","delete","remove"],a:2,e:"A single object allocated with new is released with delete. Arrays allocated with new[] require delete[]."},
{q:"What is the output of this code? int x=4; int* p=&x; *p=9; cout<<x;",o:["4","0","9","Address of x"],a:2,e:"p stores the address of x. Assigning 9 through *p changes x itself, so the output is 9."},
{q:"Which header is required to use std::cout and std::cin?",o:["<vector>","<iostream>","<string>","<iomanip>"],a:1,e:"The iostream header declares the standard input and output stream objects, including std::cin and std::cout."}
];

const cppPremiumEasyQs=[{"q":"Which header declares std::string?","o":["<cstring>","<string>","<iostream>","<sstream>"],"a":1,"e":"The <string> header declares std::string.","level":"Easy"},{"q":"Which keyword makes an initialized variable read-only through its name?","o":["static","const","extern","mutable"],"a":1,"e":"const prevents modification through that name after initialization.","level":"Easy"},{"q":"What does sizeof(char) return?","o":["0","1","2","Depends on compiler"],"a":1,"e":"sizeof(char) is defined to be 1 byte.","level":"Easy"},{"q":"Which operator returns the remainder of integer division?","o":["/","%","//","mod"],"a":1,"e":"% computes the remainder for integral operands.","level":"Easy"},{"q":"What is the value of ++x if x starts at 5?","o":["5","6","4","Undefined"],"a":1,"e":"Prefix increment increases x before yielding its value.","level":"Easy"},{"q":"Which keyword immediately exits the nearest loop?","o":["continue","break","return","goto"],"a":1,"e":"break terminates the nearest enclosing loop or switch.","level":"Easy"},{"q":"What does continue do in a loop?","o":["Ends the program","Skips to the next iteration","Terminates the loop","Restarts the function"],"a":1,"e":"continue skips the rest of the current iteration.","level":"Easy"},{"q":"Which declaration creates a pointer to int?","o":["int p*;","pointer int p;","int* p;","&int p;"],"a":2,"e":"int* p declares p as a pointer to int.","level":"Easy"},{"q":"What does nullptr represent?","o":["An integer object","A null pointer literal","An empty string","An uninitialized reference"],"a":1,"e":"nullptr is the type-safe null pointer literal.","level":"Easy"},{"q":"Which operator obtains an object's address?","o":["*","&","->","%"],"a":1,"e":"Unary & obtains an object's address.","level":"Easy"},{"q":"What is the usual entry point of a hosted C++ program?","o":["start()","main()","run()","init()"],"a":1,"e":"Execution of a hosted C++ program begins at main.","level":"Easy"},{"q":"Which declaration is a valid const integer initialized to 10?","o":["const int limit=10;","constant int limit=10;","final int limit=10;","static limit=10;"],"a":0,"e":"const int declares a constant integer.","level":"Easy"},{"q":"Which built-in type stores a character?","o":["string","char","bool","void"],"a":1,"e":"char is the fundamental character type.","level":"Easy"},{"q":"What is the result of true && false?","o":["true","false","1","Compilation error"],"a":1,"e":"Logical AND is true only when both operands are true.","level":"Easy"},{"q":"What is the result of !false?","o":["false","true","0","Undefined"],"a":1,"e":"Logical NOT reverses a Boolean value.","level":"Easy"},{"q":"Which operator represents logical OR?","o":["|","||","&&","!"],"a":1,"e":"|| is logical OR; | is bitwise OR.","level":"Easy"},{"q":"Which statement selects among constant case labels?","o":["choose","switch","select","caseof"],"a":1,"e":"switch selects a matching case based on its controlling expression.","level":"Easy"},{"q":"Which type represents true and false in C++?","o":["bool","byte","boolean","logical"],"a":0,"e":"C++ uses bool with values true and false.","level":"Easy"},{"q":"Which token begins a single-line comment?","o":["<!--","#","//","**"],"a":2,"e":"A // comment continues to the end of the line.","level":"Easy"},{"q":"Which token begins a block comment?","o":["//","/*","##","\\\\ "],"a":1,"e":"A block comment starts with /* and ends with */.","level":"Easy"},{"q":"What is the first index of a built-in array?","o":["-1","0","1","Depends on size"],"a":1,"e":"Built-in arrays use zero-based indexing.","level":"Easy"},{"q":"How many elements does int values[8] contain?","o":["7","8","9","Depends on values"],"a":1,"e":"The declared bound specifies eight elements.","level":"Easy"},{"q":"Which expression accesses the third element of a?","o":["a[3]","a[2]","a(2)","a{2}"],"a":1,"e":"The third element has index 2 because indexing starts at zero.","level":"Easy"},{"q":"Which loop is commonly used when the iteration count is known?","o":["for","switch","if","try"],"a":0,"e":"A for loop groups initialization, condition and iteration expression.","level":"Easy"},{"q":"Which loop executes its body at least once?","o":["while","for","do-while","range-for"],"a":2,"e":"do-while checks its condition after executing the body.","level":"Easy"},{"q":"What punctuation ends a do-while statement?","o":["Colon","Semicolon","Comma","None"],"a":1,"e":"A do-while statement ends with a semicolon.","level":"Easy"},{"q":"Which keyword sends a value back from a function?","o":["yield","return","break","send"],"a":1,"e":"return ends a function and optionally supplies its result.","level":"Easy"},{"q":"What does void indicate as a function return type?","o":["Returns int","Returns no value","Returns pointer","Returns bool"],"a":1,"e":"A void function does not return a value.","level":"Easy"},{"q":"Which declaration means a function takes no parameters and returns int?","o":["int f(void);","void f();","f int();","int f[];"],"a":0,"e":"int f(void) declares a no-parameter function returning int.","level":"Easy"},{"q":"What is the purpose of a function prototype?","o":["Execute a function","Declare its interface before use","Allocate its stack","Define a class"],"a":1,"e":"A declaration informs the compiler of a function's name, return type and parameters.","level":"Easy"},{"q":"Function overloading is distinguished by what?","o":["Return type alone","Parameter lists","Comments","Local variable names"],"a":1,"e":"Overloads must differ in parameter lists, not only by return type.","level":"Easy"},{"q":"Where is a local variable declared inside a block accessible?","o":["Entire program","Its enclosing block","All classes","All files"],"a":1,"e":"A block-scope variable is accessible within its scope after declaration.","level":"Easy"},{"q":"What storage duration does a typical non-static local variable have?","o":["Static","Automatic","Thread","Dynamic"],"a":1,"e":"Ordinary local variables have automatic storage duration.","level":"Easy"},{"q":"Which keyword lets a local variable retain its value between calls?","o":["extern","static","mutable","volatile"],"a":1,"e":"A static local variable is initialized once and retains its value.","level":"Easy"},{"q":"What is recursion?","o":["A function calls itself","A class inherits itself","A loop has no condition","A variable changes type"],"a":0,"e":"Recursion occurs when a function calls itself directly or indirectly.","level":"Easy"},{"q":"What helps a recursive function stop making recursive calls?","o":["A base case","A global variable","A pointer","An overload"],"a":0,"e":"A base case provides a terminating condition.","level":"Easy"},{"q":"Which keyword introduces a class definition?","o":["structonly","class","object","define"],"a":1,"e":"The class keyword introduces a class.","level":"Easy"},{"q":"What is the default access level for class members?","o":["public","protected","private","package"],"a":2,"e":"Class members are private by default.","level":"Easy"},{"q":"What is the default access level for struct members?","o":["private","protected","public","friend"],"a":2,"e":"Struct members are public by default.","level":"Easy"},{"q":"Which special function has the same name as its class and no return type?","o":["Destructor","Constructor","Getter","Operator"],"a":1,"e":"A constructor initializes an object and has the class name.","level":"Easy"},{"q":"How is the destructor of class Book named?","o":["Book()","~Book()","delete Book()","!Book()"],"a":1,"e":"A destructor uses a tilde followed by the class name.","level":"Easy"},{"q":"Can a constructor declare a return type?","o":["Yes, int","Yes, void","No","Only pointer"],"a":2,"e":"Constructors do not have return types.","level":"Easy"},{"q":"When is an automatic local object's destructor normally called?","o":["At compilation","When its scope ends","Before construction","Only with delete"],"a":1,"e":"Its destructor runs when the object's lifetime ends.","level":"Easy"},{"q":"Which access specifier restricts ordinary outside access to a class member?","o":["public","private","export","global"],"a":1,"e":"Private members are accessible to class members and friends, not ordinary outside code.","level":"Easy"},{"q":"Which access level is available to derived classes but not ordinary outside code?","o":["private","protected","public","static"],"a":1,"e":"Protected members are accessible within the class and derived classes.","level":"Easy"},{"q":"Which OOP concept allows a derived class to reuse a base class?","o":["Inheritance","Compilation","Casting","Namespacing"],"a":0,"e":"Inheritance derives a new class from an existing base class.","level":"Easy"},{"q":"Which syntax declares public inheritance from Base?","o":["class Derived : public Base {};","class Derived -> Base {};","class Derived extends Base {};","class Derived inherits Base {};"],"a":0,"e":"C++ inheritance is specified after a colon with an access mode.","level":"Easy"},{"q":"What does polymorphism mean?","o":["One interface, multiple forms","One variable only","No class methods","File storage"],"a":0,"e":"Polymorphism allows a common interface to represent different behaviors.","level":"Easy"},{"q":"Which keyword enables runtime dispatch for a member function?","o":["static","virtual","friend","inline"],"a":1,"e":"Virtual functions enable dynamic dispatch through base pointers and references.","level":"Easy"},{"q":"What is function overriding?","o":["Same name, different parameters in one scope","Derived class implementation of a virtual base function","Changing a variable","Calling a function twice"],"a":1,"e":"A derived class can override a virtual base function with a matching signature.","level":"Easy"},{"q":"Which access specifier allows unrestricted access through an accessible object?","o":["private","protected","public","static"],"a":2,"e":"Public members can be accessed by ordinary code through an accessible object.","level":"Easy"},{"q":"Which operator tests inequality?","o":["=","==","!=","<="],"a":2,"e":"!= evaluates whether two operands are unequal.","level":"Easy"},{"q":"What is 8 / 3 when both operands are integers?","o":["2","2.66","3","1"],"a":0,"e":"Integer division discards the fractional part.","level":"Easy"},{"q":"Which has higher precedence?","o":["Addition","Multiplication","Equal","Depends"],"a":1,"e":"Multiplication has higher precedence than addition.","level":"Easy"},{"q":"What does ?: denote?","o":["Loop","Conditional operator","Scope operator","Pointer operator"],"a":1,"e":"The conditional operator selects one of two expressions based on a condition.","level":"Easy"},{"q":"Which statement skips the rest of the current loop iteration?","o":["break","continue","return","switch"],"a":1,"e":"continue proceeds to the next iteration.","level":"Easy"},{"q":"What does break do inside switch?","o":["Exits the switch","Exits program","Skips a label","Repeats switch"],"a":0,"e":"break exits the nearest switch statement.","level":"Easy"},{"q":"Which is a single-precision floating type?","o":["int","float","char","bool"],"a":1,"e":"float is the standard single-precision floating-point type.","level":"Easy"},{"q":"Which type generally offers more precision than float?","o":["bool","char","double","short"],"a":2,"e":"double generally provides greater precision than float.","level":"Easy"},{"q":"Can a const object call a const member function?","o":["Yes","No","Only via new","Only in main"],"a":0,"e":"Const objects can call const-qualified member functions.","level":"Easy"},{"q":"What must a reference do when declared?","o":["Be initialized","Be reseated","Be null","Use new"],"a":0,"e":"A reference must be initialized to refer to an object.","level":"Easy"},{"q":"What does a pointer store?","o":["An address","Only a character","A class definition","A loop"],"a":0,"e":"A pointer stores an address and may also hold nullptr.","level":"Easy"},{"q":"What does *ptr access for a valid pointer?","o":["Pointer address","Pointed-to object","Pointer size","Pointer type"],"a":1,"e":"Unary * dereferences a pointer.","level":"Easy"},{"q":"Which keyword declares an entity defined elsewhere?","o":["static","extern","mutable","friend"],"a":1,"e":"extern can declare an entity with external linkage defined elsewhere.","level":"Easy"},{"q":"A function defined inside a class definition is implicitly?","o":["inline","virtual","static","friend"],"a":0,"e":"A member function defined inside its class is implicitly inline.","level":"Easy"},{"q":"Which member is shared by all objects of a class?","o":["Local variable","Static data member","Parameter","Automatic variable"],"a":1,"e":"Static data members belong to the class and are shared.","level":"Easy"},{"q":"Can a static member function use this?","o":["Yes","No","Only in constructor","Only in template"],"a":1,"e":"Static member functions have no associated object or this pointer.","level":"Easy"},{"q":"Which constructor initializes an object from another of the same type?","o":["Default","Copy","Destructor","Move assignment"],"a":1,"e":"A copy constructor initializes a new object from an existing object.","level":"Easy"},{"q":"What is a default constructor?","o":["Callable with no arguments","Destroys object","Returns int","Static method"],"a":0,"e":"A default constructor can be called without arguments.","level":"Easy"},{"q":"When are members initialized relative to constructor body?","o":["After body","Before body","During destructor","At program end"],"a":1,"e":"Base classes and data members initialize before the constructor body.","level":"Easy"},{"q":"In what order are class members initialized?","o":["Initializer-list order","Declaration order","Reverse declaration","Alphabetical"],"a":1,"e":"Members initialize in the order declared in the class.","level":"Easy"},{"q":"In what order are automatic local objects destroyed?","o":["Construction order","Reverse construction order","Alphabetical","Random"],"a":1,"e":"Automatic objects are destroyed in reverse order of completed construction.","level":"Easy"},{"q":"What is the default inheritance access for class?","o":["public","protected","private","virtual"],"a":2,"e":"Class inheritance is private by default.","level":"Easy"},{"q":"What is the default inheritance access for struct?","o":["private","protected","public","virtual"],"a":2,"e":"Struct inheritance is public by default.","level":"Easy"},{"q":"Under public inheritance, protected base members remain?","o":["Public","Protected","Private","Inaccessible"],"a":1,"e":"Protected members remain protected under public inheritance.","level":"Easy"},{"q":"How can derived code call a base implementation?","o":["super.func()","Base::func()","parent->func()","base.func()"],"a":1,"e":"A qualified call such as Base::func() selects the base implementation.","level":"Easy"},{"q":"Why is a virtual destructor useful?","o":["Safe deletion through base pointer","Sorting arrays","Overloading constructors","Namespaces"],"a":0,"e":"It ensures derived destruction when deleting through a base pointer.","level":"Easy"},{"q":"What is object slicing?","o":["Copy derived object into base object by value","Delete array","Cast int to float","Call virtual function"],"a":0,"e":"Copying by value into a base object discards the derived portion.","level":"Easy"},{"q":"Which cast supports runtime-checked downcasting?","o":["static_cast","dynamic_cast","reinterpret_cast","const_cast"],"a":1,"e":"dynamic_cast performs runtime-checked conversions in polymorphic hierarchies.","level":"Easy"},{"q":"What is required for dynamic_cast in a class hierarchy?","o":["Polymorphic source type","Static functions only","Friend function","Private constructor"],"a":0,"e":"The source type must be polymorphic, with at least one virtual function.","level":"Easy"},{"q":"Which cast changes const qualification?","o":["static_cast","dynamic_cast","const_cast","reinterpret_cast"],"a":2,"e":"const_cast adds or removes const or volatile qualification.","level":"Easy"},{"q":"Which header declares std::deque?","o":["<queue>","<deque>","<vector>","<list>"],"a":1,"e":"std::deque is declared in <deque>.","level":"Easy"},{"q":"Which container supports efficient insertion at both ends?","o":["deque","stack","set","map"],"a":0,"e":"std::deque supports efficient insertion and removal at both ends.","level":"Easy"},{"q":"Which container follows LIFO order?","o":["queue","stack","map","set"],"a":1,"e":"A stack follows last-in, first-out ordering.","level":"Easy"},{"q":"Which container follows FIFO order?","o":["stack","queue","set","array"],"a":1,"e":"A queue follows first-in, first-out ordering.","level":"Easy"},{"q":"Which stack member removes its top element?","o":["top()","pop()","front()","erase_top()"],"a":1,"e":"pop removes the top element; top accesses it.","level":"Easy"},{"q":"Which queue member accesses the next element to remove?","o":["back()","front()","top()","peek()"],"a":1,"e":"front returns the first element in a queue.","level":"Easy"},{"q":"Which container is typically a doubly linked list?","o":["list","array","vector","stack"],"a":0,"e":"std::list is a doubly linked sequence container.","level":"Easy"},{"q":"When can vector::push_back invalidate all iterators?","o":["Never","When it reallocates","Only when empty","Only for int"],"a":1,"e":"Reallocation invalidates iterators, pointers and references to vector elements.","level":"Easy"},{"q":"Which vector member checks bounds?","o":["operator[]","at()","front()","data()"],"a":1,"e":"at() throws std::out_of_range for an invalid index.","level":"Easy"},{"q":"What does vector::capacity() report?","o":["Current size","Elements before reallocation","Bytes used","Maximum standard size"],"a":1,"e":"capacity is the number of elements that fit before reallocation.","level":"Easy"},{"q":"Which algorithm searches a sorted range with binary search?","o":["find","binary_search","reverse","replace"],"a":1,"e":"std::binary_search checks membership in a sorted range.","level":"Easy"},{"q":"Which header declares std::accumulate?","o":["<algorithm>","<numeric>","<iterator>","<functional>"],"a":1,"e":"std::accumulate is declared in <numeric>.","level":"Easy"},{"q":"Which algorithm counts elements matching a predicate?","o":["count_if","sort","copy","merge"],"a":0,"e":"std::count_if counts elements for which the predicate is true.","level":"Easy"},{"q":"What does std::end(container) return?","o":["Last element","Past-the-end iterator","First element","Capacity"],"a":1,"e":"std::end returns a past-the-end iterator, which must not be dereferenced.","level":"Easy"},{"q":"Which is range-based for syntax?","o":["for(auto x : values)","while(auto x : values)","foreach values as x","loop(values)"],"a":0,"e":"Range-based for iterates over elements in a range.","level":"Easy"},{"q":"What does auto do in a declaration?","o":["Always int","Deduce type from initializer","Create pointer","Make global"],"a":1,"e":"auto lets the compiler deduce the variable type from its initializer.","level":"Easy"},{"q":"Which syntax starts a lambda with no captures or parameters?","o":["[]() {}","{}[]()","lambda() {}","() => {}"],"a":0,"e":"A lambda begins with a capture list; []() {} has no captures or parameters.","level":"Easy"},{"q":"What does capture list [=] mean?","o":["Capture used locals by value","Capture all by reference","Capture nothing","Capture only this"],"a":0,"e":"[=] captures used automatic local variables by copy.","level":"Easy"},{"q":"What does capture list [&] mean?","o":["Capture used locals by reference","Capture all by value","Capture nothing","Capture only static members"],"a":0,"e":"[&] captures used automatic local variables by reference.","level":"Easy"}];

const cppPremiumModerateQs=[{"q":"What is printed? int x=5; cout<<x++<<' '<<x;","o":["5 5","5 6","6 6","6 5"],"a":1,"e":"Post-increment yields the old value first, then increments x.","level":"Moderate"},{"q":"What is printed? int x=5; cout<<++x<<' '<<x;","o":["5 6","6 6","6 5","5 5"],"a":1,"e":"Pre-increment changes x before its value is used.","level":"Moderate"},{"q":"What is printed? int a=4; int& r=a; r+=3; cout<<a;","o":["4","7","3","Address"],"a":1,"e":"r is an alias for a, so the change is visible through a.","level":"Moderate"},{"q":"What is printed? void f(int x){x=9;} int a=2; f(a); cout<<a;","o":["9","2","0","Error"],"a":1,"e":"Pass-by-value changes only the local parameter copy.","level":"Moderate"},{"q":"What is printed? void f(int& x){x=9;} int a=2; f(a); cout<<a;","o":["9","2","0","Error"],"a":0,"e":"The reference parameter aliases the caller's variable.","level":"Moderate"},{"q":"Which declaration makes the pointer itself constant but allows changing the pointed-to int?","o":["const int* p","int* const p","const int* const p","int& p"],"a":1,"e":"int* const fixes the pointer value; the pointed-to int remains modifiable.","level":"Moderate"},{"q":"Which declaration allows p to point elsewhere but prevents modifying the int through p?","o":["int* const p","const int* p","int& const p","const int* const p"],"a":1,"e":"const int* makes the pointed-to value read-only through p while p remains reassignable.","level":"Moderate"},{"q":"What happens when a function returns a reference to its local variable?","o":["Safe copy returned","Dangling reference","Reference becomes global","Compiler extends lifetime"],"a":1,"e":"The local object's lifetime ends on return, leaving the reference dangling.","level":"Moderate"},{"q":"What does *(a+2) access for int a[]={3,6,9,12};?","o":["3","6","9","12"],"a":2,"e":"a+2 points to the third element, which contains 9.","level":"Moderate"},{"q":"What is the result of sizeof(a)/sizeof(a[0]) for int a[6] in the same scope?","o":["5","6","24","Depends on values"],"a":1,"e":"The total array size divided by one element's size gives six.","level":"Moderate"},{"q":"What is printed? int x=0; bool b=(x++ && ++x); cout<<x;","o":["0","1","2","Undefined"],"a":1,"e":"x++ yields zero, so && short-circuits and ++x is not evaluated.","level":"Moderate"},{"q":"What is printed? int n=2; switch(n){case 1:cout<<1; case 2:cout<<2; case 3:cout<<3;break;}","o":["2","23","123","3"],"a":1,"e":"Execution falls through from case 2 to case 3 because case 2 has no break.","level":"Moderate"},{"q":"Which is true about std::vector reallocation?","o":["Only end iterator invalidates","All iterators, pointers and references to elements invalidate","No references invalidate","Only first element invalidates"],"a":1,"e":"Reallocation changes the storage location and invalidates all element handles.","level":"Moderate"},{"q":"What does std::remove do to a vector range?","o":["Erases elements and shrinks size","Compacts retained values and returns a new logical end","Deletes allocated memory","Sorts values"],"a":1,"e":"remove does not change container size; combine it with erase to shrink the vector.","level":"Moderate"},{"q":"Which iterator category is required by std::sort?","o":["Input","Forward","Bidirectional","Random access"],"a":3,"e":"std::sort requires random-access iterators.","level":"Moderate"},{"q":"What is the average lookup complexity of std::unordered_map?","o":["O(1)","O(log n)","O(n log n)","O(n²)"],"a":0,"e":"Hash-table lookup is average constant time, though worst case may be linear.","level":"Moderate"},{"q":"What is the lookup complexity of std::map?","o":["O(1) average","O(log n)","O(n²)","O(2^n)"],"a":1,"e":"std::map is an ordered associative container with logarithmic lookup.","level":"Moderate"},{"q":"Which algorithm returns the first element not less than a value in a sorted range?","o":["lower_bound","upper_bound","find_if","partition"],"a":0,"e":"lower_bound finds the first position where the value can be inserted without breaking order.","level":"Moderate"},{"q":"Which algorithm returns the first element strictly greater than a value in a sorted range?","o":["lower_bound","upper_bound","binary_search","equal"],"a":1,"e":"upper_bound returns the first element greater than the searched value.","level":"Moderate"},{"q":"What does std::unique compact?","o":["All duplicates in any order","Consecutive equivalent elements","Every second element","Null pointers only"],"a":1,"e":"unique compacts consecutive equivalent elements; sorting first is common when removing all duplicates.","level":"Moderate"},{"q":"What is printed? int n=3; auto f=[n]() mutable {return ++n;}; cout<<f()<<' '<<n;","o":["4 4","4 3","3 4","3 3"],"a":1,"e":"The mutable lambda increments its captured copy; the original n remains 3.","level":"Moderate"},{"q":"What does std::move itself do?","o":["Moves resources immediately","Casts an expression to an rvalue reference","Deletes the source","Copies all members"],"a":1,"e":"std::move is a cast that enables move operations; it does not move resources by itself.","level":"Moderate"},{"q":"What is the usual state of a moved-from standard-library object?","o":["Always empty","Valid but unspecified","Destroyed","Invalid to use in any way"],"a":1,"e":"Moved-from standard-library objects remain valid, but their values are generally unspecified.","level":"Moderate"},{"q":"Which cast performs runtime-checked downcasting in a polymorphic hierarchy?","o":["static_cast","dynamic_cast","reinterpret_cast","const_cast"],"a":1,"e":"dynamic_cast checks applicable conversions at runtime.","level":"Moderate"},{"q":"What happens if a pointer dynamic_cast fails?","o":["Returns nullptr","Throws std::bad_cast","Returns false","Terminates"],"a":0,"e":"A failed pointer dynamic_cast returns nullptr; a failed reference cast throws std::bad_cast.","level":"Moderate"},{"q":"What is printed? int a=3; int b=4; cout<<(a^b);","o":["7","1","12","0"],"a":0,"e":"Bitwise XOR sets bits that differ: 3 (011) XOR 4 (100) is 7 (111).","level":"Moderate"},{"q":"What is printed? cout<<(10 & 6);","o":["2","4","6","0"],"a":0,"e":"10 is 1010 and 6 is 0110; their bitwise AND is 0010, or 2.","level":"Moderate"},{"q":"What is printed? cout<<(10 | 6);","o":["2","12","14","16"],"a":2,"e":"Bitwise OR combines 1010 and 0110 to produce 1110, which is 14.","level":"Moderate"},{"q":"What is printed? int x=5; cout<<(x++ + 2);","o":["7","8","9","10"],"a":0,"e":"Post-increment contributes the old value 5, so the sum is 7.","level":"Moderate"},{"q":"Which statement about a reference is correct?","o":["It can be reseated to another variable","It must be initialized when declared","It can be null","It owns dynamic memory"],"a":1,"e":"A C++ reference must be initialized and remains bound to its referred object.","level":"Moderate"},{"q":"Which operator accesses a member through an object pointer?","o":[".","->","::","*."],"a":1,"e":"The arrow operator accesses a member through a pointer to an object.","level":"Moderate"},{"q":"Which operator is used for scope resolution?","o":[".",":","::","->"],"a":2,"e":"The scope resolution operator :: qualifies names in a namespace or class.","level":"Moderate"},{"q":"What does the explicit keyword commonly prevent?","o":["Inheritance","Implicit conversions through a constructor or conversion function","Function overloading","Virtual dispatch"],"a":1,"e":"explicit prevents unintended implicit conversions for applicable constructors and conversion functions.","level":"Moderate"},{"q":"Which special member function transfers resources from an expiring object?","o":["Copy constructor","Move constructor","Destructor","Default constructor"],"a":1,"e":"A move constructor can transfer resources from an rvalue source.","level":"Moderate"},{"q":"What is the result of declaring a member function as static?","o":["It receives this pointer","It belongs to the class rather than an individual object","It becomes virtual","It can access every non-static member directly"],"a":1,"e":"A static member function has no this pointer and belongs to the class.","level":"Moderate"},{"q":"Which initialization form is associated with uniform initialization in modern C++?","o":["Parentheses only","Brace initialization","Assignment only","new operator only"],"a":1,"e":"Brace initialization provides uniform initialization syntax and helps prevent narrowing conversions.","level":"Moderate"},{"q":"What does auto do in a variable declaration?","o":["Makes variable global","Deducts the type from its initializer","Makes variable constant","Allocates memory dynamically"],"a":1,"e":"auto asks the compiler to deduce the variable type from its initializer.","level":"Moderate"},{"q":"What does decltype(expr) determine?","o":["Runtime value of expr","Type of an expression","Size of an object","Address of expr"],"a":1,"e":"decltype yields a type based on the declared type and value category of its operand.","level":"Moderate"},{"q":"Which loop is guaranteed to execute its body at least once?","o":["for","while","do-while","range-for"],"a":2,"e":"A do-while checks its condition after executing the body.","level":"Moderate"},{"q":"What does break do inside a loop?","o":["Skips current iteration only","Terminates the nearest enclosing loop","Restarts the loop","Terminates the program"],"a":1,"e":"break exits the nearest enclosing loop or switch statement.","level":"Moderate"},{"q":"What does continue do inside a loop?","o":["Ends the program","Exits all nested loops","Skips to the next iteration","Restarts the program"],"a":2,"e":"continue skips the remaining statements in the current iteration.","level":"Moderate"},{"q":"Which statement about an enum class is correct?","o":["Its enumerators are injected into the enclosing scope","It is strongly scoped and does not implicitly convert to int","It cannot specify an underlying type","It is a runtime object"],"a":1,"e":"Scoped enumerations avoid implicit integer conversion and keep enumerator names scoped.","level":"Moderate"},{"q":"What does sizeof(char) always return in C++?","o":["0","1","2","Implementation-defined value"],"a":1,"e":"sizeof(char) is defined to be exactly one byte.","level":"Moderate"},{"q":"Which allocation form is paired with delete[]?","o":["new","new[]","malloc","calloc"],"a":1,"e":"Memory allocated with new[] must be released using delete[].","level":"Moderate"},{"q":"What happens if ordinary new cannot allocate the requested storage?","o":["Returns nullptr by default","Throws std::bad_alloc","Returns -1","Calls delete automatically"],"a":1,"e":"The throwing form of new reports allocation failure by throwing std::bad_alloc.","level":"Moderate"},{"q":"Which header provides std::unique_ptr and std::shared_ptr?","o":["<memory>","<utility>","<new>","<algorithm>"],"a":0,"e":"The standard smart pointer types are declared in the memory header.","level":"Moderate"},{"q":"Which statement about a constexpr variable is correct?","o":["It must be initialized with a constant expression","It is always stored on the heap","It can change at runtime","It must be a pointer"],"a":0,"e":"A constexpr variable must be initialized with a constant expression.","level":"Moderate"},{"q":"What is a namespace primarily used for?","o":["Dynamic allocation","Avoiding name collisions by grouping identifiers","Creating threads","Overloading operators automatically"],"a":1,"e":"Namespaces organize names and reduce naming conflicts.","level":"Moderate"},{"q":"Which function is the entry point of a hosted C++ program?","o":["start()","main()","init()","run()"],"a":1,"e":"A hosted C++ program begins execution at main.","level":"Moderate"},{"q":"Which statement about inline functions is correct?","o":["The compiler must always substitute the body at each call","The inline specifier permits definitions in multiple translation units under ODR rules","Inline functions cannot be recursive","Only class members can be inline"],"a":1,"e":"inline is primarily an ODR/linkage facility; it does not force call-site substitution.","level":"Moderate"},{"q":"What is printed? int x=12; cout<<(x>>2);","o":["2","3","4","6"],"a":1,"e":"Right-shifting 12 (1100) by two positions gives 3.","level":"Moderate"},{"q":"What is printed? int x=3; cout<<(x<<2);","o":["6","9","12","16"],"a":2,"e":"Left-shifting 3 by two positions gives 12.","level":"Moderate"},{"q":"Which expression checks whether n is even?","o":["n%2==1","n/2==0","n%2==0","n*2==0"],"a":2,"e":"An even integer has remainder zero when divided by 2.","level":"Moderate"},{"q":"What is 17/5 when both operands are int?","o":["3.4","3","4","2"],"a":1,"e":"Integer division discards the fractional part.","level":"Moderate"},{"q":"What is printed? double x=5/2; cout<<x;","o":["2","2.5","3","Compilation error"],"a":0,"e":"Integer division occurs before conversion to double.","level":"Moderate"},{"q":"Which cast performs a runtime-checked downcast in a polymorphic hierarchy?","o":["static_cast","reinterpret_cast","dynamic_cast","const_cast"],"a":2,"e":"dynamic_cast checks casts in polymorphic class hierarchies.","level":"Moderate"},{"q":"Which cast changes const qualification?","o":["const_cast","dynamic_cast","static_cast","reinterpret_cast"],"a":0,"e":"const_cast adds or removes cv-qualification.","level":"Moderate"},{"q":"Why use a virtual destructor in a base class?","o":["Prevent object creation","Ensure derived destruction through a base pointer","Make all methods virtual","Avoid constructors"],"a":1,"e":"A virtual destructor ensures proper destruction through a base pointer.","level":"Moderate"},{"q":"Which member can a derived class override?","o":["A non-virtual function","An eligible virtual base member","A constructor","A static member"],"a":1,"e":"A derived class overrides an eligible virtual member function.","level":"Moderate"},{"q":"What does override ensure?","o":["Function is overloaded","Function actually overrides a base virtual function","Function is inline","Class cannot be inherited"],"a":1,"e":"The compiler diagnoses a function that does not override a base virtual function.","level":"Moderate"},{"q":"What makes a class abstract?","o":["At least one pure virtual function","No data members","Only static methods","The abstract keyword"],"a":0,"e":"A class with a pure virtual function cannot be instantiated directly.","level":"Moderate"},{"q":"Which declaration is a pure virtual function?","o":["virtual void f();","void f()=0;","virtual void f()=0;","static void f()=0;"],"a":2,"e":"A pure virtual function is declared virtual and assigned = 0.","level":"Moderate"},{"q":"What is object slicing?","o":["Copying only the base portion of a derived object into a base object","Deleting twice","Converting a pointer to void","Splitting an array"],"a":0,"e":"Copying a derived object by value into a base object discards its derived-specific portion.","level":"Moderate"},{"q":"Which inheritance mode makes public and protected base members protected in the derived class?","o":["public","private","protected","virtual"],"a":2,"e":"Protected inheritance makes public and protected base members protected.","level":"Moderate"},{"q":"What is a friend function allowed to do?","o":["Become a member","Access private and protected members","Override virtual functions","Allocate objects"],"a":1,"e":"A friend function is not a member but is granted private and protected access.","level":"Moderate"},{"q":"Which statement about constructors is correct?","o":["They have a return type","They can be virtual","They initialize objects and use the class name","They are always inherited"],"a":2,"e":"A constructor has the class name and initializes a newly created object.","level":"Moderate"},{"q":"When is a local automatic object's destructor called?","o":["At compilation","When execution leaves its scope","Only with delete","Only at program termination"],"a":1,"e":"An automatic object's lifetime ends when its scope is exited.","level":"Moderate"},{"q":"How should a const data member be initialized?","o":["Assignment in constructor body","Member initializer list","Setter later","Destructor"],"a":1,"e":"A const data member must be initialized in the constructor initializer list.","level":"Moderate"},{"q":"What is printed? int a[]={2,4,6}; cout<<*(a+1);","o":["2","4","6","Address"],"a":1,"e":"a+1 points to the second array element.","level":"Moderate"},{"q":"In most expressions, an array name converts to what?","o":["Pointer to its first element","Reference to whole array","Array length","Null pointer"],"a":0,"e":"Array-to-pointer conversion produces a pointer to the first element in most expressions.","level":"Moderate"},{"q":"Which container offers constant-time indexed random access?","o":["std::list","std::vector","std::forward_list","std::set"],"a":1,"e":"std::vector supports constant-time random access by index.","level":"Moderate"},{"q":"Which vector operation may invalidate all iterators if reallocation occurs?","o":["push_back","size","empty","capacity"],"a":0,"e":"push_back can reallocate when capacity is insufficient.","level":"Moderate"},{"q":"Which STL algorithm sorts a range?","o":["find","reverse","sort","count"],"a":2,"e":"std::sort orders elements in the specified half-open range.","level":"Moderate"},{"q":"Which header declares std::sort?","o":["<vector>","<algorithm>","<iterator>","<numeric>"],"a":1,"e":"std::sort is declared in the algorithm header.","level":"Moderate"},{"q":"What does std::map store?","o":["Unique ordered keys associated with values","Duplicate keys only","Unordered values without keys","Only integer pairs"],"a":0,"e":"std::map stores unique keys mapped to values in key order.","level":"Moderate"},{"q":"Which container stores elements as key-value pairs with average constant-time lookup by key?","o":["std::vector","std::unordered_map","std::list","std::stack"],"a":1,"e":"std::unordered_map uses hashing and provides average constant-time lookup by key.","level":"Moderate"},{"q":"Which container follows the Last-In, First-Out principle?","o":["std::queue","std::deque","std::stack","std::set"],"a":2,"e":"A stack removes the most recently inserted element first.","level":"Moderate"},{"q":"Which container follows the First-In, First-Out principle?","o":["std::stack","std::queue","std::map","std::priority_queue"],"a":1,"e":"A queue removes elements in the order they were inserted.","level":"Moderate"},{"q":"What does std::priority_queue return from top() by default?","o":["Smallest element","Largest element","Oldest element","Random element"],"a":1,"e":"The default priority_queue is a max-heap, so top() returns the largest element.","level":"Moderate"},{"q":"Which operation removes the last element of a std::vector?","o":["erase_front()","pop_back()","remove_last()","delete()"],"a":1,"e":"pop_back() removes the final element of a vector.","level":"Moderate"},{"q":"What does vector::at(index) do when index is out of range?","o":["Returns zero","Throws std::out_of_range","Silently wraps around","Always returns the last element"],"a":1,"e":"at() performs bounds checking and throws std::out_of_range for an invalid index.","level":"Moderate"},{"q":"Which statement about std::list is correct?","o":["It supports constant-time random indexing","It is a doubly linked list in the standard library","Its elements must be contiguous","It cannot insert in the middle"],"a":1,"e":"std::list is a doubly linked list; it does not provide constant-time random access.","level":"Moderate"},{"q":"Which iterator category is supported by std::forward_list?","o":["Random-access","Bidirectional","Forward","Contiguous"],"a":2,"e":"forward_list provides forward iterators that move in one direction.","level":"Moderate"},{"q":"What does the erase-remove idiom commonly accomplish for a vector?","o":["Sorts the vector","Removes matching elements and compacts the remaining range","Reverses the vector","Makes the vector immutable"],"a":1,"e":"The remove algorithm moves retained values forward; erase then removes the trailing elements.","level":"Moderate"},{"q":"Which algorithm finds the first element satisfying a condition?","o":["std::find_if","std::sort","std::accumulate","std::reverse"],"a":0,"e":"find_if searches a range for the first element for which the predicate is true.","level":"Moderate"},{"q":"Which standard algorithm calculates a sum over a range?","o":["std::merge","std::accumulate","std::partition","std::unique"],"a":1,"e":"std::accumulate combines range elements using an operation, addition by default.","level":"Moderate"},{"q":"Which header declares std::accumulate?","o":["<numeric>","<algorithm>","<vector>","<functional>"],"a":0,"e":"std::accumulate is declared in the numeric header.","level":"Moderate"},{"q":"What does a lambda expression create?","o":["A namespace","An anonymous function object","A new thread","A template specialization"],"a":1,"e":"A lambda expression defines a closure object that can be called like a function.","level":"Moderate"},{"q":"In a lambda capture list, what does [=] generally mean?","o":["Capture used local variables by value","Capture all variables by reference","Capture no variables","Capture only this by reference"],"a":0,"e":"[=] captures odr-used local variables by copy.","level":"Moderate"},{"q":"In a lambda capture list, what does [&] generally mean?","o":["Capture used local variables by reference","Capture all variables by value","Capture no variables","Capture only global variables"],"a":0,"e":"[&] captures odr-used local variables by reference.","level":"Moderate"},{"q":"What is a function template used for?","o":["Define a function pattern that works with multiple types","Create a function at runtime from a string","Prevent function calls","Replace every class"],"a":0,"e":"Function templates allow the compiler to instantiate type-specific functions from a generic definition.","level":"Moderate"},{"q":"What is a class template?","o":["A blueprint for generating classes parameterized by types or values","A class that cannot have methods","A runtime-only object","A namespace alias"],"a":0,"e":"Class templates define families of classes parameterized by types or non-type values.","level":"Moderate"},{"q":"Which keyword introduces a template parameter list?","o":["generic","template","typename_only","parameter"],"a":1,"e":"The template keyword introduces a template declaration and its parameter list.","level":"Moderate"},{"q":"Which statement about exceptions is correct?","o":["A catch block can handle a matching thrown exception","Every exception must be an integer","throw can only appear in main","finally is a C++ keyword"],"a":0,"e":"A matching catch handler handles an exception thrown from a try block.","level":"Moderate"},{"q":"What is std::exception commonly used for?","o":["A standard base class for many library exception types","A container for integers","A thread scheduler","A memory allocator"],"a":0,"e":"Many standard library exception classes derive from std::exception.","level":"Moderate"},{"q":"What does RAII stand for in C++?","o":["Resource Acquisition Is Initialization","Runtime Array Index Inspection","Reference Assignment Is Immediate","Resource Access Inheritance Interface"],"a":0,"e":"RAII ties resource lifetime to object lifetime, typically acquiring in constructors and releasing in destructors.","level":"Moderate"},{"q":"Which smart pointer expresses exclusive ownership of a dynamically managed object?","o":["std::shared_ptr","std::weak_ptr","std::unique_ptr","void*"],"a":2,"e":"unique_ptr has exclusive ownership and cannot be copied, but can be moved.","level":"Moderate"},{"q":"What is the main role of std::weak_ptr?","o":["Own an object exclusively","Observe a shared_ptr-managed object without extending its lifetime","Delete all shared pointers","Allocate arrays on the stack"],"a":1,"e":"weak_ptr is a non-owning observer that can be checked or converted temporarily to shared_ptr.","level":"Moderate"},{"q":"What can cause a reference cycle involving std::shared_ptr to leak memory?","o":["Reference counts never reach zero","The compiler disables destructors","Pointers become stack variables","The object is copied by value"],"a":0,"e":"A shared_ptr cycle can keep reference counts above zero; weak_ptr can break ownership cycles.","level":"Moderate"},{"q":"Which statement best describes std::move?","o":["It moves an object immediately in every case","It casts an expression to an rvalue reference, enabling move-aware operations","It deletes the source object","It copies an object into a new thread"],"a":1,"e":"std::move is a cast that enables overload resolution to select move operations; the actual move depends on the operation.","level":"Moderate"}];

const javaQs=[
{q:"Which component executes Java bytecode and enables Java programs to run on different operating systems?",o:["JVM","JDK compiler only","Javadoc","Java source file"],a:0,e:"The Java Virtual Machine executes bytecode. A compatible JVM on each platform provides the runtime environment."},
{q:"Which statement about Java primitive types is correct?",o:["String is a primitive type","int is a primitive type","Array is a primitive type","Integer is a primitive type"],a:1,e:"int is one of Java's eight primitive types. String, arrays and Integer are reference types."},
{q:"What is the default value of an instance variable of type boolean when it is not explicitly initialized?",o:["true","false","null","0"],a:1,e:"Instance fields of boolean type receive the default value false. Local variables do not receive automatic default initialization."},
{q:"Which keyword is used to create an object in Java?",o:["alloc","new","create","object"],a:1,e:"The new operator creates an object, invokes its constructor and returns a reference to it."},
{q:"Which OOP principle bundles data and the methods that operate on it while controlling access to the data?",o:["Inheritance","Encapsulation","Polymorphism","Abstraction"],a:1,e:"Encapsulation groups state and behavior in a class and uses access control to protect internal state."},
{q:"Which Java keyword prevents a class from being subclassed?",o:["static","final","abstract","private"],a:1,e:"A class declared final cannot be extended by another class."},
{q:"Which statement about method overloading is correct?",o:["Methods must have different names","Methods share a name but have different parameter lists","Only return types must differ","It requires inheritance"],a:1,e:"Overloaded methods have the same name with different parameter lists. Return type alone cannot distinguish overloads."},
{q:"Which annotation indicates that a method is intended to override a superclass method?",o:["@Overload","@Inherited","@Override","@FunctionalInterface"],a:2,e:"@Override asks the compiler to verify that the method correctly overrides a method from a superclass or implements an interface method."},
{q:"What happens when a Java class declares no constructor?",o:["The compiler supplies a default no-argument constructor","The class cannot be instantiated","Every field must be static","The JVM creates a constructor at runtime"],a:0,e:"If no constructor is declared, the compiler provides a default no-argument constructor."},
{q:"Which access modifier makes a top-level class accessible from other packages, subject to module and classpath visibility?",o:["private","protected","public","static"],a:2,e:"A top-level class can be declared public to make it accessible outside its package."},
{q:"Which type of class cannot be instantiated directly and may contain abstract methods?",o:["Final class","Abstract class","Wrapper class","Nested enum"],a:1,e:"An abstract class cannot be instantiated directly and can declare abstract methods that concrete subclasses implement."},
{q:"Which statement about a Java interface is correct?",o:["A class can implement multiple interfaces","An interface can be instantiated with new","A class can extend multiple classes","Interfaces cannot contain default methods"],a:0,e:"A Java class may implement multiple interfaces. Interfaces cannot be instantiated directly and can include default methods."},
{q:"Which class is immutable and represents a sequence of characters?",o:["StringBuilder","StringBuffer","String","char[]"],a:2,e:"String objects are immutable: operations that appear to modify a String create another String instead."},
{q:"Which class is generally preferred for building a string through repeated modifications in a single thread?",o:["StringBuilder","String","Character","StringTokenizer"],a:0,e:"StringBuilder is mutable and avoids creating a new String object for every append operation. It is not synchronized."},
{q:"Which superclass is the root of Java's exception hierarchy?",o:["Exception","RuntimeException","Throwable","Error"],a:2,e:"Throwable is the root class for objects that can be thrown and caught, including Exception and Error."},
{q:"Which block is normally used to execute cleanup code whether or not an exception occurs?",o:["throws","finally","throw","assert"],a:1,e:"A finally block normally runs after try/catch processing and is commonly used for cleanup. try-with-resources is preferred for many closeable resources."},
{q:"Which collection interface represents an ordered sequence that permits duplicate elements?",o:["Set","List","Map","Queue only"],a:1,e:"List represents an ordered sequence and permits duplicate elements."},
{q:"Which collection type stores key-value mappings and requires keys to be unique?",o:["List","Set","Map","Deque"],a:2,e:"Map associates each key with a value; a map cannot contain duplicate keys."},
{q:"What is the purpose of the Runnable interface in Java?",o:["Represent a task whose run method can be executed by a thread","Store key-value pairs","Create an immutable string","Handle SQL connections"],a:0,e:"Runnable represents a task through its run() method and can be supplied to a Thread or an executor."},
{q:"Which keyword ensures that only one thread at a time can execute a synchronized instance method on the same object monitor?",o:["volatile","transient","synchronized","native"],a:2,e:"A synchronized instance method acquires that object's monitor, so another thread must wait to enter a synchronized method or block using the same monitor."}
];

const dsaJavaPremiumModerateQs=[["What is the time complexity of the following code?\n\n```\nfor (int i = 0; i \u003c n; i++) {\n    for (int j = i; j \u003c n; j++) {\n        System.out.println(i + j);\n    }\n}\n```",["\\\\(O(n\\log n)\\\\)","\\\\(O(n)\\\\)","\\\\(O(\\log n)\\\\)","\\\\(O(n^2)\\\\)"],3,"The inner loop executes \\\\(n+(n-1)+\\cdots+1\\\\) times, which equals \\\\(n(n+1)/2\\\\). Therefore, complexity is \\\\(O(n^2)\\\\)."],["What is the time complexity of the following code?\n\n```\nint i = 1;\nwhile (i \u003c n) {\n    i = i * 3;\n}\n```",["\\\\(O(n\\log n)\\\\)","\\\\(O(n^2)\\\\)","\\\\(O(n)\\\\)","\\\\(O(\\log_3 n)\\\\)"],3,"The variable is multiplied by 3 in every iteration. The loop executes approximately \\\\(\\log_3 n\\\\) times."],["What is the time complexity of this recurrence?\n\n\\\\[ T(n)=T(n/2)+O(1) \\\\]",["\\\\(O(n)\\\\)","\\\\(O(n^2)\\\\)","\\\\(O(n\\log n)\\\\)","\\\\(O(\\log n)\\\\)"],3,"The input size is halved in every recursive call. The number of calls is logarithmic."],["Which complexity grows fastest as \\\\(n\\\\) becomes very large?",["\\\\(O(n^2)\\\\)","\\\\(O(n\\log n)\\\\)","\\\\(O(2^n)\\\\)","\\\\(O(n!)\\\\)"],3,"Factorial growth eventually exceeds exponential growth, polynomial growth, and logarithmic growth."],["What is the time complexity of inserting an element at the beginning of an ArrayList containing \\\\(n\\\\) elements?",["\\\\(O(n\\log n)\\\\)","\\\\(O(\\log n)\\\\)","\\\\(O(1)\\\\)","\\\\(O(n)\\\\)"],3,"Existing elements must be shifted one position to the right, requiring linear time."],["Which notation represents a tight asymptotic bound?",["Little-o","Big-O","Big-Omega","Big-Theta"],3,"Big-Theta represents an asymptotically tight bound, giving both upper and lower bounds."],["What is the time complexity of the following code?\n\n```\nfor (int i = 1; i \u003c= n; i++) {\n    for (int j = 1; j \u003c= n; j += i) {\n        // operation\n    }\n}\n```",["\\\\(O(n^2)\\\\)","\\\\(O(\\log n)\\\\)","\\\\(O(n)\\\\)","\\\\(O(n\\log n)\\\\)"],3,"For each outer iteration \\\\(i\\\\), the inner loop executes approximately \\\\(n/i\\\\) times. The total is \\\\(n\\sum\\_{i=1}^{n}1/i=O(n\\log n)\\\\)."],["An algorithm requires 5 seconds for an input size of 100. If its complexity is quadratic, approximately how long will it require for an input size of 200?",["15 seconds","40 seconds","10 seconds","20 seconds"],3,"Doubling the input size in a quadratic algorithm multiplies execution time by 2² = 4. Therefore, 5 × 4 = 20 seconds."],["Which of the following is an example of an in-place sorting algorithm?",["Merge Sort","Radix Sort","Counting Sort","Selection Sort"],3,"Standard Selection Sort sorts by swapping elements within the original array and requires \\\\(O(1)\\\\) auxiliary space."],["What is the worst-case time complexity of searching for an element in an unsorted array using Linear Search?",["\\\\(O(1)\\\\)","\\\\(O(\\log n)\\\\)","\\\\(O(n\\log n)\\\\)","\\\\(O(n)\\\\)"],3,"In the worst case, the element is at the last position or is absent, so all \\\\(n\\\\) elements must be checked."],["What is the output of the following code?\n\n```\nint[] a = {2, 4, 6, 8};\nint sum = 0;\n\nfor (int i = 0; i \u003c a.length; i += 2) {\n    sum += a[i];\n}\nSystem.out.println(sum);\n```",["20","14","10","8"],3,"The loop visits indices 0 and 2. Their values are 2 and 6, so the printed sum is 8."],["Which technique is commonly used to find the maximum sum of a subarray of fixed size \\\\(k\\\\) efficiently?",["Binary Search","Divide and Conquer","DFS","Sliding Window"],3,"Sliding Window calculates the first window sum and updates it by adding the new element and subtracting the outgoing element. This gives \\\\(O(n)\\\\) time."],["What is the output?\n\n```\nint[] a = {1, 2, 3, 4, 5};\nint left = 0, right = 4;\n\nwhile (left \u003c right) {\n    int temp = a[left];\n    a[left] = a[right];\n    a[right] = temp;\n    left++;\n    right--;\n}\nSystem.out.println(a[2]);\n```",["2","4","5","3"],3,"The array becomes `{5,4,3,2,1}`. The middle element remains 3."],["What is the result of the following operation?\n\n```\nint[] a = {10, 20, 30, 40, 50};\nSystem.out.println(a[a.length - 2]);\n```",["50","10","30","40"],3,"The array length is 5. The second-last index is 3, containing 40."],["Which technique is most suitable for finding a pair of numbers with a given sum in a sorted array?",["DFS","Stack","Merge Sort","Two Pointers"],3,"Start with pointers at both ends. If their sum is too small, move the left pointer forward; if too large, move the right pointer backward."],["What is the output?\n\n```\nint[] a = {3, 5, 7, 9};\nSystem.out.println(a[1] + a[3]);\n```",["16","12","18","14"],3,"Index 1 contains 5 and index 3 contains 9. Their sum is 14."],["Which algorithm is suitable for finding the equilibrium index of an array, where the sum of elements on the left equals the sum on the right?",["Heap Sort","Binary Search","Quick Sort","Prefix Sum"],3,"Calculate the total sum first. Maintain a left sum while traversing. At each index, compare the left sum with total sum minus left sum and the current element."],["What is the time complexity of rotating an array by one position using reversal operations?",["\\\\(O(n^2)\\\\)","\\\\(O(1)\\\\)","\\\\(O(\\log n)\\\\)","\\\\(O(n)\\\\)"],3,"Reversing the required portions of the array involves processing elements a constant number of times, resulting in \\\\(O(n)\\\\)."],["Which data structure is most appropriate for implementing a prefix sum over an array when frequent range-sum queries are required and the array does not change?",["Stack","Queue","Binary Heap","Prefix Sum Array"],3,"A prefix sum array allows a range sum to be calculated using two prefix values in \\\\(O(1)\\\\) time after \\\\(O(n)\\\\) preprocessing."],["What is the output?\n\n```\nint[] a = {4, 8, 12, 16};\nint count = 0;\n\nfor (int x : a) {\n    if (x % 8 == 0)\n        count++;\n}\nSystem.out.println(count);\n```",["3","4","1","2"],3,"The numbers divisible by 8 are 8 and 16. Therefore, the count is 2."],["What is the time complexity of inserting a node at the beginning of a singly linked list?",["\\\\(O(n)\\\\)","\\\\(O(n^2)\\\\)","\\\\(O(\\log n)\\\\)","\\\\(O(1)\\\\)"],3,"Create a new node, point it to the current head, and update the head pointer. No traversal is needed."],["Which pointer is updated when deleting the last node of a singly linked list containing more than one node?",["The next node's previous pointer","The head pointer only","The tail's next pointer only","The previous node's next pointer"],3,"Traverse to the second-last node and set its next pointer to null."],["What is the time complexity of traversing a linked list containing \\\\(n\\\\) nodes?",["\\\\(O(n^2)\\\\)","\\\\(O(\\log n)\\\\)","\\\\(O(1)\\\\)","\\\\(O(n)\\\\)"],3,"Each node is visited exactly once."],["Which linked-list type allows traversal in both forward and backward directions?",["Header Linked List","Singly Linked List","Circular Singly Linked List","Doubly Linked List"],3,"A doubly linked list maintains both next and previous pointers."],["What is the output of this conceptual linked-list operation?\n\n```\n// List: 10 -> 20 -> 30 -> 40\n// Delete the node containing 20\n// Print the list\n```",["10 -> 20 -> 30 -> 40","20 -> 30 -> 40","10 -> 20 -> 40","10 -> 30 -> 40"],3,"The node containing 20 is removed by changing the next pointer of the node containing 10 to point to 30."],["Which algorithm finds the middle node of a singly linked list in one traversal?",["Slow and Fast Pointer Technique","Merge Sort","Insertion Sort","Binary Search"],0,"The slow pointer moves one step and the fast pointer moves two steps. When the fast pointer reaches the end, the slow pointer is at the middle."],["What is the main advantage of a circular linked list over a standard singly linked list?",["Its last node points back to the first node.","It supports backward traversal automatically.","It supports random indexing.","It always uses less memory."],0,"The last node points to the head, allowing continuous traversal without reaching a null pointer."],["What is the time complexity of accessing the last element of a singly linked list when only the head pointer is available?",["\\\\(O(n)\\\\)","\\\\(O(\\log n)\\\\)","\\\\(O(1)\\\\)","\\\\(O(n\\log n)\\\\)"],0,"The list must be traversed until a node with a null next pointer is found."],["Which operation is more efficient in a doubly linked list when a pointer to the node to be deleted is already available?",["Deleting the node","Finding the middle node","Sorting the list","Searching for the node"],0,"The previous and next nodes can be connected directly. Deletion takes \\\\(O(1)\\\\) time, assuming the node is not subject to special head/tail restrictions."],["Which sorting algorithm is generally preferred for a linked list?",["Merge Sort","Heap Sort","Selection Sort","Quick Sort"],0,"Merge Sort works efficiently with linked lists because splitting and merging can be done through pointer manipulation without random access."],["Which principle does a stack follow?",["LIFO","FIFO","Random Access","Priority Based"],0,"Stack follows Last In, First Out. The last inserted element is removed first."],["Which operation inserts an element into a stack?",["Push","Peek","Dequeue","Pop"],0,"Push inserts an element at the top of a stack."],["What is the output?\n\n```\nStack\u003cInteger> s = new Stack\u003c>();\ns.push(10);\ns.push(20);\ns.push(30);\ns.pop();\nSystem.out.println(s.peek());\n```",["20","10","Empty","30"],0,"After pushing 10, 20, and 30, the top is 30. Pop removes 30, so peek returns 20."],["Which principle does a standard queue follow?",["FIFO","Priority Based","LIFO","Random Access"],0,"Queue follows First In, First Out. The first inserted element is removed first."],["Which data structure is used internally for standard recursive function calls?",["Stack","Graph","Heap","Queue"],0,"Function calls are managed through the call stack, which stores return addresses, parameters, and local execution information."],["Which operation returns the front element of a queue without removing it?",["Peek","Push","Enqueue","Dequeue"],0,"Peek returns the front element without changing the queue."],["What is the main advantage of a circular queue?",["It avoids wasting array positions after dequeue operations.","It automatically sorts elements.","It supports random access in constant time.","It uses two stacks."],0,"Circular indexing allows freed positions at the beginning of the array to be reused."],["A queue is implemented using two stacks. If each element is pushed onto the input stack once and transferred to the output stack at most once, what is the amortized time complexity of each dequeue operation?",["O(1) amortized","O(n) amortized","O(n²) amortized","O(log n) amortized"],0,"Each element moves between stacks at most once. Across a sequence of operations, total transfer work is linear, so dequeue is O(1) amortized."],["Which data structure is commonly used in Breadth-First Search?",["Queue","Stack","Binary Search Tree","Priority Queue"],0,"BFS uses a queue to process vertices in the order they are discovered."],["A queue is implemented using a linked list with head and tail pointers. What is the time complexity of enqueue at the tail?",["\\\\(O(1)\\\\)","\\\\(O(\\log n)\\\\)","\\\\(O(n)\\\\)","\\\\(O(n^2)\\\\)"],0,"The tail pointer directly identifies the insertion location. A new node can be appended in constant time."],["What is the output?\n\n```\nint fun(int n) {\n    if (n == 0)\n        return 1;\n    return n * fun(n - 1);\n}\nSystem.out.println(fun(4));\n```",["24","20","12","16"],0,"The function calculates factorial: \\\\(4!=4\\times3\\times2\\times1=24\\\\)."],["What is the time complexity of iterative Binary Search?",["\\\\(O(\\log n)\\\\)","\\\\(O(1)\\\\)","\\\\(O(n)\\\\)","\\\\(O(n\\log n)\\\\)"],0,"Every iteration eliminates approximately half of the remaining search space."],["What is the output?\n\n```\nint fun(int n) {\n    if (n \u003c= 1)\n        return n;\n    return fun(n - 1) + fun(n - 2);\n}\nSystem.out.println(fun(5));\n```",["5","3","8","13"],0,"The function generates Fibonacci numbers: 0, 1, 1, 2, 3, 5. Therefore, fun(5) returns 5."],["Which condition is necessary for applying Binary Search to an array?",["The array must be sorted according to the search ordering.","The array must contain only positive numbers.","The array must contain distinct values.","The array must be circular."],0,"Binary Search depends on sorted order to eliminate half of the remaining elements."],["What is the base case in a recursive function?",["The condition that stops further recursive calls","The first loop iteration","The recursive call itself","The last variable declaration"],0,"The base case terminates recursion and prevents infinite recursive calls."],["Which searching algorithm works particularly well when data is sorted and uniformly distributed?",["Interpolation Search","DFS","Linear Search","BFS"],0,"Interpolation Search estimates the target's position using its value. Under uniform distribution, its average complexity is \\\\(O(\\log\\log n)\\\\)."],["What is the output?\n\n```\nvoid print(int n) {\n    if (n == 0)\n        return;\n    System.out.print(n + \" \");\n    print(n - 1);\n}\nprint(3);\n```",["3 2 1","0 1 2 3","3 2 1 0","1 2 3"],0,"The number is printed before the recursive call, producing 3, 2, 1."],["An unbounded sorted array supports access by increasing index. Which search strategy can locate a target at position p in O(log p) time without knowing the array length?",["Exponential Search followed by Binary Search","Depth-First Search","Interpolation Search","Linear Search from index 0"],0,"Exponential Search brackets the target by doubling the index, then applies Binary Search within that range."],["What is the worst-case time complexity of Linear Search?",["\\\\(O(n)\\\\)","\\\\(O(\\log n)\\\\)","\\\\(O(n^2)\\\\)","\\\\(O(1)\\\\)"],0,"Linear Search may need to inspect every element before finding the target or concluding that it is absent."],["Which problem is commonly solved using backtracking?",["N-Queens Problem","Calculating array length","Finding the maximum element","Finding an element in a sorted array"],0,"Backtracking explores possible queen placements and reverses a placement whenever it violates the constraints."],["Which traversal visits the root node before its left and right subtrees?",["Inorder","Preorder","Level Order","Postorder"],1,"Preorder follows Root → Left → Right."],["Which traversal visits the left subtree, root, and then right subtree?",["Postorder","Inorder","Preorder","Level Order"],1,"Inorder follows Left → Root → Right."],["What is the output of the inorder traversal of this BST?\n\n```\n       40\n      /  \\\n    20    60\n   / \\    / \\\n 10  30  50  70\n```",["40, 60, 70, 50, 20, 30, 10","10, 20, 30, 40, 50, 60, 70","10, 30, 20, 50, 70, 60, 40","40, 20, 10, 30, 60, 50, 70"],1,"Inorder traversal visits the left subtree, root, and right subtree. A BST produces ascending order."],["What is the maximum number of children a binary tree node can have?",["4","2","1","3"],1,"A binary tree node can have at most two children: left and right."],["Which data structure is used for level-order traversal of a binary tree?",["Stack","Queue","Heap","HashMap"],1,"A queue processes nodes level by level in FIFO order."],["In a Binary Search Tree, where are values smaller than the root generally placed?",["Parent node","Left subtree","Any random location","Right subtree"],1,"In the standard BST property, keys smaller than a node are stored in its left subtree and larger keys in its right subtree."],["Which data structure is used to efficiently implement a priority queue?",["Stack","Binary Heap","Circular Queue","Linked List only"],1,"A binary heap supports efficient insertion and removal of the highest- or lowest-priority element in \\\\(O(\\log n)\\\\)."],["What is the time complexity of searching in a balanced BST?",["\\\\(O(n^2)\\\\)","\\\\(O(\\log n)\\\\)","\\\\(O(n)\\\\)","\\\\(O(1)\\\\)"],1,"A balanced BST has logarithmic height, so searching requires \\\\(O(\\log n)\\\\) comparisons."],["What is the height of a tree containing only one root node, when measured in edges?",["2","0","-1","1"],1,"A single-node tree has no edges, so its height is zero when measured in edges."],["Which rotation corrects an LL imbalance in an AVL tree?",["No Rotation","Right Rotation","Left Rotation","Double Left Rotation"],1,"A single right rotation corrects the left-left imbalance."],["Which traversal is suitable for deleting a binary tree safely?",["Inorder","Postorder","Preorder","Level Order only"],1,"Postorder processes child nodes before the parent, so subtrees can be deleted before their root."],["In a max-heap, what is the relationship between a parent and its children?",["Parent must be equal to both children.","Parent is greater than or equal to its children.","No ordering property exists.","Parent is always smaller than its children."],1,"Every parent in a max-heap has a value greater than or equal to its children."],["Which tree is self-balancing?",["Ordinary Binary Tree","AVL Tree","General Tree","Skewed Binary Tree"],1,"An AVL tree maintains a balance factor of -1, 0, or +1 at every node."],["In a zero-based array representation of a binary heap, what is the index of the parent of the node at index i, for i > 0?",["2*i + 2","floor((i - 1) / 2)","2*i + 1","floor(i / 2) + 1"],1,"For a zero-based heap array, the parent index is floor((i - 1) / 2)."],["Which data structure is generally used to implement heap-based priority queues?",["Graph","Array","Stack","Doubly Linked List"],1,"A binary heap is commonly stored in an array because parent-child relationships can be calculated using indices."],["Which sorting algorithm repeatedly selects the smallest element from the unsorted portion?",["Merge Sort","Selection Sort","Bubble Sort","Insertion Sort"],1,"Selection Sort finds the minimum element in the unsorted section and swaps it into its correct position."],["What is the worst-case time complexity of Bubble Sort?",["\\\\(O(n)\\\\)","\\\\(O(n^2)\\\\)","\\\\(O(n\\log n)\\\\)","\\\\(O(\\log n)\\\\)"],1,"In reverse-sorted input, Bubble Sort performs approximately \\\\(n(n-1)/2\\\\) comparisons."],["Which sorting algorithm builds a sorted portion by inserting each new element into its correct position?",["Quick Sort","Insertion Sort","Counting Sort","Heap Sort"],1,"Insertion Sort takes each element and inserts it into the appropriate position in the already-sorted portion."],["What is the average-case time complexity of Quick Sort?",["\\\\(O(n^2)\\\\)","\\\\(O(n\\log n)\\\\)","\\\\(O(\\log n)\\\\)","\\\\(O(n)\\\\)"],1,"With reasonably balanced partitions, Quick Sort performs \\\\(O(n\\log n)\\\\) work on average."],["Which sorting algorithm is stable in its standard implementation?",["Selection Sort","Merge Sort","Heap Sort","Standard in-place Quick Sort"],1,"Merge Sort can preserve the relative order of equal elements by selecting from the left half first when keys are equal."],["What is a collision in hashing?",["When a hash function returns zero","When two different keys map to the same hash-table index","When an array becomes full","When a key is deleted"],1,"A collision occurs when two distinct keys produce the same table index."],["Which collision-resolution technique stores multiple elements in a linked list at the same hash-table index?",["Quadratic Probing","Separate Chaining","Linear Probing","Double Hashing"],1,"Separate chaining maintains a collection, commonly a linked list, at each table index to store colliding keys."],["What is the average-case lookup complexity of a well-distributed hash table?",["\\\\(O(n)\\\\)","\\\\(O(1)\\\\)","\\\\(O(\\log n)\\\\)","\\\\(O(n\\log n)\\\\)"],1,"A good hash function distributes keys across the table, allowing expected constant-time lookup."],["Which sorting algorithm is appropriate when the range of integer values is small compared with the number of elements?",["Heap Sort","Counting Sort","Merge Sort","Quick Sort"],1,"Counting Sort uses a frequency array for the limited range of values and can run in \\\\(O(n+k)\\\\)."],["What is the purpose of rehashing in a hash table?",["To reverse all stored keys","To reduce collisions by creating a larger table and redistributing keys","To delete duplicate values automatically","To sort the keys"],1,"Rehashing expands the table when its load factor becomes too high and recalculates positions for stored keys."],["Which algorithm explores a graph by visiting all adjacent vertices before moving to the next level?",["Dijkstra","DFS","BFS","Kruskal"],2,"Breadth-First Search explores vertices level by level using a queue."],["Which data structure is commonly used in Depth-First Search?",["Circular Queue","Heap","Stack","Queue"],2,"DFS uses a stack, either explicitly or through recursive function calls."],["What is the time complexity of DFS using an adjacency list?",["\\\\(O(\\log V)\\\\)","\\\\(O(V^2)\\\\)","\\\\(O(V+E)\\\\)","\\\\(O(E^2)\\\\)"],2,"Each vertex is visited once and each edge is examined a constant number of times."],["Which algorithm finds the shortest path from a source in a weighted graph with non-negative edge weights?",["Kruskal","Prim","Dijkstra","DFS"],2,"Dijkstra repeatedly selects the unprocessed vertex with the smallest tentative distance and relaxes its outgoing edges."],["What is a spanning tree of a connected undirected graph?",["A graph containing all possible edges","A graph containing only cycles","A subgraph that includes all vertices and has no cycles","A tree containing only one vertex"],2,"A spanning tree connects all vertices without cycles and contains exactly \\\\(V-1\\\\) edges."],["Which algorithm is used to construct a Minimum Spanning Tree by selecting edges in increasing order of weight?",["BFS","Bellman-Ford","Kruskal","Dijkstra"],2,"Kruskal's algorithm processes edges in ascending order and adds an edge if it does not create a cycle."],["Which data structure is useful for efficiently checking whether adding an edge creates a cycle in Kruskal's algorithm?",["Queue","Stack","Disjoint Set Union","Binary Heap only"],2,"DSU determines whether two vertices belong to the same connected component. If they do, adding the edge creates a cycle."],["What is the maximum number of edges in a simple directed graph with \\\\(V\\\\) vertices and no self-loops?",["\\\\(2V\\\\)","\\\\(V^2\\\\)","\\\\(V(V-1)\\\\)","\\\\(V(V-1)/2\\\\)"],2,"Each vertex can have directed edges to all other \\\\(V-1\\\\) vertices, giving \\\\(V(V-1)\\\\) possible edges."],["Which algorithm is suitable for detecting a cycle in a directed graph using DFS?",["Heap Sort","Prim's Algorithm","DFS with recursion-stack tracking or three-color marking","Binary Search"],2,"If DFS encounters a vertex currently on the recursion path (gray state), a back edge exists and a directed cycle is present."],["Which graph representation is generally more space-efficient for a sparse graph?",["Adjacency Matrix","Two-dimensional array","Adjacency List","Complete Matrix"],2,"An adjacency list requires \\\\(O(V+E)\\\\) space, while an adjacency matrix requires \\\\(O(V^2)\\\\)."],["What is the main purpose of Topological Sorting?",["To find the shortest weighted path","To detect the maximum degree","To arrange vertices according to directed dependency relationships","To find the minimum spanning tree"],2,"Topological sorting places every vertex before its dependent vertices in a DAG."],["Which algorithm can calculate shortest paths in a graph with negative edge weights?",["Prim","BFS","Bellman-Ford","Kruskal"],2,"Bellman-Ford supports negative edges and detects reachable negative-weight cycles."],["What is the number of edges in a tree with 25 vertices?",["26","25","24","50"],2,"A tree with \\\\(V\\\\) vertices has \\\\(V-1\\\\) edges. Therefore, \\\\(25-1=24\\\\)."],["Which algorithm is used to find all-pairs shortest paths in a weighted graph?",["Kruskal","BFS","Floyd-Warshall","Prim"],2,"Floyd-Warshall computes shortest distances between every pair of vertices using dynamic programming."],["A graph is connected if:",["It contains only directed edges.","Every vertex has exactly two edges.","A path exists between every pair of vertices.","It contains no cycles."],2,"In an undirected connected graph, every vertex can be reached from every other vertex."],["Which approach is most suitable for solving the 0/1 Knapsack problem using dynamic programming?",["Greedy selection by value-to-weight ratio","Binary Search only","A two-dimensional DP table based on items and capacity","DFS without storing results"],2,"DP considers each item and each capacity, choosing between including or excluding the item. Its standard time complexity is \\\\(O(nW)\\\\)."],["Which problem is commonly solved using the Greedy approach?",["0/1 Knapsack in its general form","Longest Common Subsequence","Fractional Knapsack","Matrix Chain Multiplication"],2,"Fractional Knapsack allows taking parts of items. Selecting items in decreasing value-to-weight ratio gives an optimal solution."],["What is the time complexity of calculating Fibonacci numbers using bottom-up dynamic programming?",["\\\\(O(2^n)\\\\)","\\\\(O(\\log n)\\\\)","\\\\(O(n)\\\\)","\\\\(O(n^2)\\\\)"],2,"Each Fibonacci value is calculated once using previously computed values. The time complexity is \\\\(O(n)\\\\)."],["In Matrix Chain Multiplication, what does dp[i][j] usually represent?",["The maximum dimension among matrices i through j","The number of matrices between i and j","The minimum scalar multiplications needed to multiply matrices i through j","The number of ways to sort matrices i through j"],2,"dp[i][j] stores the minimum scalar multiplications needed to compute matrices i through j, considering every split point."],["What is the time complexity of the standard dynamic programming solution for LCS of strings of lengths \\\\(m\\\\) and \\\\(n\\\\)?",["\\\\(O(\\log(m+n))\\\\)","\\\\(O(m^2+n^2)\\\\)","\\\\(O(mn)\\\\)","\\\\(O(m+n)\\\\)"],2,"The DP table has \\\\((m+1)(n+1)\\\\) entries, and each entry is computed in constant time."],["Which problem can be optimally solved using a greedy strategy based on selecting the earliest finishing activity?",["Longest Common Subsequence","0/1 Knapsack","Activity Selection","Matrix Chain Multiplication"],2,"Selecting the activity that finishes earliest leaves the maximum remaining time for compatible activities."],["What is the main property of overlapping subproblems in Dynamic Programming?",["Every subproblem is completely independent.","The problem has no recursive structure.","The same smaller problems are solved repeatedly.","Only one subproblem exists."],2,"Overlapping subproblems occur when the same smaller problems appear multiple times. DP stores their results to avoid repeated computation."],["In job sequencing with deadlines, where every job takes one unit of time, which greedy strategy is commonly used to maximize total profit?",["Schedule every job in input order","Always schedule the job with the earliest deadline first","Process jobs by decreasing profit and place each in the latest free slot at or before its deadline","Choose jobs by increasing profit"],2,"Process jobs in decreasing profit order and place each in the latest free slot not exceeding its deadline."],["What is the time complexity of the standard greedy activity-selection algorithm after sorting activities by finishing time?",["\\\\(O(n^2)\\\\)","\\\\(O(\\log n)\\\\)","\\\\(O(n)\\\\)","\\\\(O(n\\log n)\\\\)"],2,"Once the activities are sorted, a single traversal selects compatible activities in \\\\(O(n)\\\\). Including sorting, total complexity is \\\\(O(n\\log n)\\\\)."],["Which technique is most appropriate for finding the minimum number of coins for a given amount when arbitrary coin denominations are supplied and the greedy strategy is not guaranteed to work?",["Heap Sort","Binary Search","Dynamic Programming","Linear Search"],2,"Dynamic Programming examines possible coin choices for each amount and stores the minimum number of coins needed. It works even when greedy selection is not optimal."]].map(([q,o,a,e])=>({q,o,a,e,level:"Moderate"}));

const dsaJavaPremiumHardQs=[["What is the time complexity of the following code?\n\n```\nfor (int i = 1; i \u003c n; i *= 2) {\n    for (int j = 0; j \u003c i; j++) {\n        // constant operation\n    }\n}\n```",["\\\\(O(n\\log n)\\\\)","\\\\(O(\\log n)\\\\)","\\\\(O(n)\\\\)","\\\\(O(n^2)\\\\)"],2,"The inner loop executes \\\\(1+2+4+8+\\cdots+n/2\\\\) times. This geometric series sums to \\\\(O(n)\\\\), not \\\\(O(n\\log n)\\\\)."],["What is the time complexity of this recurrence?\n\n\\\\[ T(n)=2T(n/2)+n\\log n \\\\]",["\\\\(O(n\\log^2 n)\\\\)","\\\\(O(n\\log n)\\\\)","\\\\(O(n^2)\\\\)","\\\\(O(\\log^2 n)\\\\)"],0,"By the Master Theorem, \\\\(a=2,b=2\\\\), and \\\\(f(n)=n\\log n\\\\). This is the extended case where the resulting complexity is \\\\(O(n\\log^2 n)\\\\)."],["Which recurrence represents the worst-case time complexity of randomized Quick Sort when the pivot repeatedly produces partitions of sizes 0 and \\\\(n-1\\\\)?",["\\\\(T(n)=2T(n/2)+O(n)\\\\)","\\\\(T(n)=T(n-1)+O(\\log n)\\\\)","\\\\(T(n)=T(n/2)+O(n)\\\\)","\\\\(T(n)=T(n-1)+O(n)\\\\)"],3,"Each partition processes \\\\(n\\\\) elements and leaves a subproblem of size \\\\(n-1\\\\). Summation gives \\\\(n+(n-1)+\\cdots+1=O(n^2)\\\\)."],["An algorithm has time complexity \\\\(O(n^3)\\\\). If the input size doubles, approximately how many times does its execution time increase?",["2 times","8 times","4 times","6 times"],1,"Doubling the input gives \\\\((2n)^3=8n^3\\\\)."],["Which statement about amortized analysis is correct?",["It calculates only the worst-case cost of one operation.","It bounds the average cost per operation over a sequence of operations, without requiring a probability distribution.","It calculates average performance over randomly generated inputs.","It ignores expensive operations."],1,"Amortized analysis considers a sequence of operations. An expensive operation can be compensated for by many inexpensive operations."],["What is the time complexity of the following code?\n\n```\nfor (int i = n; i > 1; i /= 2) {\n    for (int j = 1; j \u003c= n; j *= 2) {\n        System.out.println(i + j);\n    }\n}\n```",["\\\\(O(\\log n)\\\\)","\\\\(O(n)\\\\)","\\\\(O(\\log^2 n)\\\\)","\\\\(O(n\\log n)\\\\)"],2,"Both loops execute \\\\(O(\\log n)\\\\) times. Their combined complexity is \\\\(O(\\log^2 n)\\\\)."],["An algorithm uses \\\\(O(n)\\\\) auxiliary space due to recursion. Which technique can potentially reduce its auxiliary space to \\\\(O(1)\\\\) without changing its asymptotic time complexity?",["Memoization","Adding another recursive call","Tail-recursion elimination","Increasing the input array size"],2,"Tail-recursion elimination can replace tail-recursive calls with iteration, avoiding additional call-stack frames. This depends on implementation support or manually converting the recursion."],["What is the complexity of the recurrence?\n\n\\\\[ T(n)=T(n-1)+T(n-2)+O(1) \\\\]",["\\\\(O(n^2)\\\\)","\\\\(O(\\log n)\\\\)","\\\\(O(2^n)\\\\)","\\\\(O(n)\\\\)"],2,"This recurrence resembles naive recursive Fibonacci computation. Its growth is exponential, approximately \\\\(O(\\varphi^n)\\\\), which is bounded by \\\\(O(2^n)\\\\)."],["Which statement about a comparison-based sorting algorithm is correct?",["It can sort in \\\\(O(n)\\\\) worst-case time for arbitrary distinct keys.","It must be stable.","Its worst-case lower bound is \\\\(\\Omega(n\\log n)\\\\).","It always requires \\\\(O(n)\\\\) auxiliary space."],2,"Comparison sorting has a decision-tree lower bound of \\\\(\\Omega(n\\log n)\\\\) in the worst case."],["Consider an algorithm with complexity \\\\(O(n\\log n)\\\\). Which input size gives the greatest growth in operation count?",["\\\\(n=2000\\\\)","\\\\(n=500\\\\)","\\\\(n=100\\\\)","\\\\(n=1000\\\\)"],0,"For \\\\(n\\log n\\\\), the operation count increases with input size. Therefore, 2000 produces the greatest growth."],["An array contains positive and negative integers. Which algorithm finds the maximum sum of a contiguous subarray in \\\\(O(n)\\\\) time?",["Kadane's Algorithm","Floyd's Algorithm","Binary Search","Prim's Algorithm"],0,"Kadane's algorithm maintains the maximum subarray sum ending at each position and the global maximum. It uses \\\\(O(n)\\\\) time and \\\\(O(1)\\\\) extra space."],["An array of size \\\\(n\\\\) contains elements from 1 to \\\\(n\\\\), with exactly one duplicate and one missing value. Which approach can identify both in \\\\(O(n)\\\\) time and \\\\(O(1)\\\\) auxiliary space?",["Use a frequency array of size \\\\(n\\\\).","Sort the array using Merge Sort.","Use a nested-loop comparison.","Use mathematical sum and sum-of-squares equations."],3,"The difference between expected and actual sums and sums of squares provides two equations that can determine the duplicate and missing values."],["How many distinct contiguous windows of size k can be formed in an array of n elements, where n is at least k?",["n + k","n - k + 1","n","n - k"],1,"A window of length k can start at indices 0 through n-k, giving (n-k)+1 distinct windows."],["Given a sorted array containing duplicate values, which approach finds the first occurrence of a target in \\\\(O(\\log n)\\\\)?",["Modified binary search that continues searching left after a match.","Hashing every element.","Standard binary search returning immediately when the target matches.","Linear search from the beginning."],0,"After finding the target, continue searching the left half while storing the matching index."],["An array is sorted and then rotated at an unknown pivot. Which algorithm finds a target in \\\\(O(\\log n)\\\\), assuming all elements are distinct?",["Modified Binary Search","Linear Search","Merge Sort","Counting Sort"],0,"At each step, at least one half is sorted. Determine which half contains the target and eliminate the other half."],["What is the minimum number of swaps required to bring all elements less than or equal to \\\\(k\\\\) together in an array?",["Number of elements less than \\\\(k\\\\)","Minimum number of elements greater than \\\\(k\\\\) in any window of size equal to the number of elements less than or equal to \\\\(k\\\\)","Array length divided by two","Number of elements greater than \\\\(k\\\\) in the entire array"],1,"The desired group has a fixed window size. Every element greater than \\\\(k\\\\) inside the window must be swapped with a suitable element outside it."],["Which data structure is most suitable for efficiently finding the median of a continuously arriving stream of integers?",["Two Heaps","Binary Search Tree without balancing","Single Stack","Single Queue"],0,"A max-heap stores the smaller half and a min-heap stores the larger half. Their roots provide the median in \\\\(O(1)\\\\) after \\\\(O(\\log n)\\\\) insertion."],["An array has positive integers. Which technique is most suitable for finding the smallest subarray with sum greater than or equal to a given positive value?",["DFS","Topological Sorting","Sliding Window with two pointers","Heap Sort"],2,"Since all elements are positive, expanding and shrinking the window maintains a valid sum efficiently. The complexity is \\\\(O(n)\\\\)."],["What is the worst-case time complexity of finding the kth largest element using Quickselect?",["\\\\(O(n)\\\\)","\\\\(O(n\\log n)\\\\)","\\\\(O(n^2)\\\\)","\\\\(O(\\log n)\\\\)"],2,"Quickselect has expected \\\\(O(n)\\\\) complexity, but repeatedly poor pivots can produce \\\\(O(n^2)\\\\) worst-case complexity."],["Which technique is most suitable for finding all pairs in an array whose sum equals a target, with expected \\\\(O(n)\\\\) time?",["HashSet or HashMap","Selection Sort","Nested loops only","Binary Tree Traversal"],0,"For every element \\\\(x\\\\), check whether target minus \\\\(x\\\\) has already been encountered. Hash-based lookup gives expected constant-time operations."],["Which algorithm detects a cycle in a singly linked list using \\\\(O(1)\\\\) auxiliary space?",["Merge Sort","Binary Search","Floyd's Cycle Detection Algorithm","Dijkstra's Algorithm"],2,"Two pointers move at different speeds. If a cycle exists, the faster pointer eventually meets the slower pointer."],["In a singly linked list, which operation requires \\\\(O(n)\\\\) time if only the head pointer is available?",["Accessing the kth node","Checking whether the head is null","Deleting the first node","Inserting a node at the beginning"],0,"A singly linked list does not support direct indexing. Traversal is required to reach the kth node."],["In Floyd's cycle detection algorithm, after the slow and fast pointers meet, how can the starting node of the cycle be found?",["Move both pointers two steps at a time from the head.","Move both pointers one step at a time, starting one at the head and the other at the meeting point.","Reverse the entire list.","Delete the meeting node."],1,"After the pointers meet, reset one pointer to the head. Move both one step at a time. Their next meeting point is the cycle entry."],["What is the time complexity of merging two sorted singly linked lists of lengths \\\\(m\\\\) and \\\\(n\\\\)?",["\\\\(O(mn)\\\\)","\\\\(O(1)\\\\)","\\\\(O(\\log(m+n))\\\\)","\\\\(O(m+n)\\\\)"],3,"Each node is examined and linked exactly once, resulting in linear time."],["Which pointer arrangement is required to reverse a singly linked list iteratively?",["Slow and fast only","Only current","Previous, current, and next","Head and tail only"],2,"The previous pointer stores the reversed portion, current processes the present node, and next preserves the remaining list."],["A circular linked list contains \\\\(n\\\\) nodes. What is the time complexity of finding its last node when only the head pointer is available?",["\\\\(O(\\log n)\\\\)","\\\\(O(1)\\\\)","\\\\(O(n)\\\\)","\\\\(O(n^2)\\\\)"],2,"Without a tail pointer, traversal is required until the node whose next pointer points to the head is found."],["Which algorithm is most suitable for sorting a singly linked list in \\\\(O(n\\log n)\\\\) time?",["Selection Sort","Merge Sort","Heap Sort","Bubble Sort"],1,"Merge Sort efficiently splits and merges linked lists without requiring random access."],["In a doubly linked list, what is the minimum number of pointer updates generally needed to insert a node between two existing adjacent nodes?",["4","2","1","6"],0,"The new node's previous and next pointers must be assigned, and the neighboring nodes' next and previous pointers must be updated."],["Two singly linked lists intersect at a node. Which approach finds their intersection in \\\\(O(m+n)\\\\) time and \\\\(O(1)\\\\) auxiliary space?",["Compare their lengths and align the starting positions","Sort both lists","Reverse both lists and compare values","Use nested loops"],0,"Advance the pointer of the longer list by the length difference. Then move both pointers together until they reach the same node or null."],["A singly linked list is sorted in ascending order. Which approach efficiently removes all duplicate nodes?",["Compare every node with every other node.","Traverse once and compare each node with its next node.","Reverse the list twice.","Apply DFS."],1,"In a sorted list, duplicate values are adjacent. One traversal is sufficient, giving \\\\(O(n)\\\\) time."],["Which data structure is most suitable for evaluating a postfix expression?",["Graph","Queue","Heap","Stack"],3,"Operands are pushed onto the stack. When an operator appears, the required operands are popped, evaluated, and the result is pushed back."],["What is the maximum number of elements in a circular queue implemented using an array of size \\\\(N\\\\), with a separate counter variable?",["\\\\(N/2\\\\)","\\\\(N\\\\)","\\\\(N-1\\\\)","\\\\(N+1\\\\)"],1,"A counter tracks the current number of elements, allowing all \\\\(N\\\\) array positions to be used."],["Which data structure is used to implement the next greater element problem efficiently?",["Circular Queue","Min-Heap","Monotonic Stack","Hash Table only"],2,"A monotonic decreasing stack maintains unresolved elements. When a larger element arrives, it resolves smaller elements from the stack."],["What is the time complexity of finding the largest element in a sliding window of size \\\\(k\\\\) using a deque?",["\\\\(O(n\\log n)\\\\)","\\\\(O(nk)\\\\)","\\\\(O(k^2)\\\\)","\\\\(O(n)\\\\)"],3,"Each index enters and leaves the deque at most once, so the complete operation is linear."],["Which data structure combination is commonly used to implement an LRU cache with \\\\(O(1)\\\\) average get and put operations?",["Stack and Queue","Two Stacks","Binary Search Tree and Array","HashMap and Doubly Linked List"],3,"The HashMap provides constant-time lookup, while the doubly linked list allows constant-time removal and movement of recently used nodes."],["Which condition indicates stack overflow in an array-based stack of capacity \\\\(N\\\\), using zero-based indexing?",["top == N-1","top == N","top == -1","top == 0"],0,"The last available index is \\\\(N-1\\\\). A push operation cannot proceed when the stack is already at this index."],["Which technique can be used to implement a queue using two stacks with amortized \\\\(O(1)\\\\) enqueue and dequeue operations?",["Use recursion for every dequeue.","Sort both stacks after every insertion.","Push into both stacks for every operation.","Use one stack for enqueue and transfer elements to the second stack only when it is empty."],3,"Each element is transferred at most once from the input stack to the output stack. Therefore, the amortized cost per operation is \\\\(O(1)\\\\)."],["What is the result of the postfix expression?\n\n```\n8 2 3 * + 4 -\n```",["14","12","10","8"],2,"\\\\(2\\times3=6\\\\), \\\\(8+6=14\\\\), and \\\\(14-4=10\\\\)."],["Which data structure is most appropriate for checking whether parentheses in an expression are balanced?",["Queue","Stack","Heap","HashMap"],1,"Opening brackets are pushed. Each closing bracket must match the most recently opened bracket, following LIFO order."],["A deque supports insertion and deletion at both ends. Which operation combination makes it useful for implementing both a stack and a queue?",["Delete from both ends only","Insert from both ends only","Insert front and delete rear only","Insert rear and delete front for a queue; insert and delete at the same end for a stack"],3,"FIFO behavior is obtained using opposite ends, while LIFO behavior is obtained by using the same end for both insertion and deletion."],["How many recursive calls are made in the following function, including the initial call?\n\n```\nvoid fun(int n) {\n    if (n \u003c= 1) return;\n    fun(n / 2);\n    fun(n / 2);\n}\n```\n\nFor \\\\(n=8\\\\), assume integer division.",["8","7","16","15"],3,"The recursion forms a full binary tree with 8 leaves and 15 total nodes (calls)."],["Which technique is most appropriate for solving the N-Queens problem?",["Backtracking","Binary Search","Greedy Search","Counting Sort"],0,"Backtracking places queens one by one, checks constraints, and reverses invalid placements."],["When generating all permutations by in-place swapping and backtracking, what auxiliary space is required by the recursion stack, excluding the output collection?",["O(n!)","O(1)","O(log n)","O(n)"],3,"The recursion fixes one position per level and reaches depth n. In-place swaps avoid an additional permutation-sized working array, so the auxiliary call-stack space is O(n), excluding stored output."],["What is the maximum recursion depth of binary search on an array containing \\\\(n\\\\) elements?",["\\\\(O(n\\log n)\\\\)","\\\\(O(\\log n)\\\\)","\\\\(O(n)\\\\)","\\\\(O(\\sqrt n)\\\\)"],1,"Each recursive call halves the search interval."],["Which approach solves the subset-sum problem when all subsets must be examined in the general case?",["Prim's Algorithm","Heap Sort","Backtracking or exhaustive search","Binary Search only"],2,"Each of the \\\\(n\\\\) elements can either be included or excluded, producing up to \\\\(2^n\\\\) subsets."],["What is the primary purpose of memoization in recursive algorithms?",["Store previously computed results to avoid repeated calculations","Reduce memory to zero","Convert all algorithms into sorting algorithms","Increase recursive depth"],0,"Memoization caches subproblem results, improving efficiency when subproblems overlap."],["How many different permutations can be generated from \\\\(n\\\\) distinct elements?",["\\\\(2^n\\\\)","\\\\(n\\log n\\\\)","\\\\(n^2\\\\)","\\\\(n!\\\\)"],3,"The first position has \\\\(n\\\\) choices, the second has \\\\(n-1\\\\), and so on. Total permutations equal \\\\(n!\\\\)."],["Which problem is a classic example of divide-and-conquer recursion?",["Breadth-First Search","Linear Search","Hash Lookup","Merge Sort"],3,"Merge Sort divides the input into halves, recursively sorts each half, and merges the results."],["If an algorithm explicitly outputs every subset of an n-element set, what is its time complexity when writing the elements of every subset is counted?",["O(n·2^n)","O(2^n)","O(n!)","O(n log n)"],0,"There are 2^n subsets, and across all subsets each of the n elements appears in exactly 2^(n-1) subsets. The total output size is n·2^(n-1), which is O(n·2^n)."],["Which statement about tail recursion is correct?",["It cannot be converted into iteration.","The recursive call must always be the first statement.","It always has exponential complexity.","No computation remains after the recursive call returns."],3,"In tail recursion, the recursive call is the final operation. It can often be converted into an iterative loop."],["A binary tree contains \\\\(n\\\\) nodes. What is the maximum number of edges it can contain?",["\\\\(n+1\\\\)","\\\\(n\\\\)","\\\\(n-1\\\\)","\\\\(2n\\\\)"],2,"Every connected tree with \\\\(n\\\\) vertices has exactly \\\\(n-1\\\\) edges."],["What is the maximum number of nodes at level \\\\(l\\\\) in a binary tree, assuming the root is at level 0?",["\\\\(l^2\\\\)","\\\\(2^l\\\\)","\\\\(2l\\\\)","\\\\(2^{l+1}\\\\)"],1,"Every level can contain twice as many nodes as the previous level. Therefore, level \\\\(l\\\\) has at most \\\\(2^l\\\\) nodes."],["Which traversal of a Binary Search Tree produces the keys in ascending order?",["Postorder","Level order","Preorder","Inorder"],3,"Inorder traversal visits left subtree, root, and right subtree, producing sorted order in a BST with distinct keys."],["What is the worst-case search complexity of an unbalanced Binary Search Tree containing \\\\(n\\\\) nodes?",["\\\\(O(1)\\\\)","\\\\(O(n)\\\\)","\\\\(O(n\\log n)\\\\)","\\\\(O(\\log n)\\\\)"],1,"A BST can become skewed, resembling a linked list. Searching may require visiting every node."],["What is the balance factor of an AVL tree node?",["Number of leaf nodes","Height of right subtree minus height of left subtree","Height of left subtree minus height of right subtree","Number of children"],2,"The conventional AVL balance factor is left-subtree height minus right-subtree height. Its allowed values are -1, 0, and +1."],["Which AVL rotation is required when insertion occurs in the left subtree of the left child?",["RL Rotation","LL Rotation","LR Rotation","RR Rotation"],1,"The LL imbalance is corrected using a single right rotation."],["Which AVL rotation is required when insertion occurs in the right subtree of the left child?",["RR Rotation","LL Rotation","RL Rotation","LR Rotation"],3,"The LR imbalance requires a left rotation on the left child followed by a right rotation on the unbalanced node."],["What is the time complexity of building a binary heap from an unsorted array using bottom-up heap construction?",["\\\\(O(n^2)\\\\)","\\\\(O(n)\\\\)","\\\\(O(n\\log n)\\\\)","\\\\(O(\\log n)\\\\)"],1,"Bottom-up heap construction takes linear time because most nodes are near the leaves and require little or no downward adjustment."],["In a max-heap, which element is guaranteed to be at the root?",["Maximum element","Median element","Second-largest element","Minimum element"],0,"The max-heap property ensures that every parent is greater than or equal to its children."],["What is the time complexity of deleting the maximum element from a binary max-heap containing \\\\(n\\\\) elements?",["\\\\(O(1)\\\\)","\\\\(O(n\\log n)\\\\)","\\\\(O(\\log n)\\\\)","\\\\(O(n)\\\\)"],2,"The root is replaced by the last element, followed by heapify-down, which takes logarithmic time."],["Which traversal is most useful for deleting an entire binary tree?",["Level order only","Inorder","Postorder","Preorder"],2,"Postorder visits children before the parent, ensuring subtrees are processed before their root."],["A full binary tree contains 15 internal nodes. How many leaves does it contain?",["16","30","14","15"],0,"In a full binary tree, the number of leaves is one more than the number of internal nodes: \\\\(L=I+1=16\\\\)."],["Which statement about a complete binary tree is correct?",["Every leaf must be at the same level.","The tree must be a BST.","Every node must have exactly two children.","All levels except possibly the last are completely filled, and the last level is filled from left to right."],3,"This is the defining property of a complete binary tree and makes it suitable for array-based heap representation."],["Which data structure is most appropriate for finding the kth smallest element in a large BST?",["Queue sorting","Inorder traversal with a counter","BFS without a counter","Stack only"],1,"Inorder traversal visits BST elements in sorted order. Stop when the counter reaches \\\\(k\\\\). The time depends on how many nodes are visited."],["What is the height of a perfectly balanced binary tree containing \\\\(2^h-1\\\\) nodes, when height is measured in edges?",["\\\\(h\\\\)","\\\\(h-1\\\\)","\\\\(2h\\\\)","\\\\(2^h\\\\)"],1,"The root is at level 0 and the deepest level is \\\\(h-1\\\\), so the height in edges is \\\\(h-1\\\\)."],["Which sorting algorithm has \\\\(O(n\\log n)\\\\) worst-case time complexity and is stable in its standard implementation?",["Quick Sort","Heap Sort","Merge Sort","Selection Sort"],2,"Merge Sort has guaranteed \\\\(O(n\\log n)\\\\) time and preserves the relative order of equal elements when implemented stably."],["What is the worst-case time complexity of Heap Sort?",["\\\\(O(n)\\\\)","\\\\(O(n\\log n)\\\\)","\\\\(O(\\log n)\\\\)","\\\\(O(n^2)\\\\)"],1,"Building the heap takes \\\\(O(n)\\\\), followed by \\\\(n\\\\) extractions, each requiring \\\\(O(\\log n)\\\\)."],["Which sorting algorithm performs particularly well when the input is nearly sorted?",["Insertion Sort","Selection Sort","Counting Sort","Heap Sort"],0,"Insertion Sort requires relatively few shifts when elements are already close to their correct positions. Its best-case complexity is \\\\(O(n)\\\\)."],["A data set is too large to fit in main memory. Which sorting method is designed to sort it efficiently using disk files and sequential merging?",["External Merge Sort","Insertion Sort","Heap Sort","Quick Sort"],0,"External Merge Sort sorts chunks that fit in memory, writes sorted runs to disk, and merges those runs in passes. Sequential I/O makes it suitable for data larger than RAM."],["Which sorting algorithm is non-comparison-based and can achieve \\\\(O(n+k)\\\\) time for integers in a suitable range?",["Heap Sort","Quick Sort","Merge Sort","Counting Sort"],3,"Counting Sort counts occurrences of values in a limited range and reconstructs the sorted output."],["What is the worst-case complexity of searching in a hash table using separate chaining?",["\\\\(O(n\\log n)\\\\)","\\\\(O(n)\\\\)","\\\\(O(\\log n)\\\\)","\\\\(O(1)\\\\)"],1,"If all keys collide into one chain, searching may require traversing all \\\\(n\\\\) elements."],["In open addressing with linear probing, what is primary clustering?",["Deletion of every alternate key","Increasing the table size automatically","Formation of long consecutive occupied blocks","Multiple keys having the same original hash value only"],2,"Linear probing causes consecutive occupied slots to form clusters, increasing the number of probes for future insertions and searches."],["Which collision-resolution method uses a secondary hash function to determine the probe interval?",["Linear Probing","Quadratic Probing","Separate Chaining","Double Hashing"],3,"Double hashing uses a second hash function to calculate the step size between successive probes."],["What is the load factor of a hash table?",["Number of stored keys divided by table capacity","Table capacity divided by number of keys","Number of collisions divided by table capacity","Number of empty slots divided by stored keys"],0,"Load factor \\\\(\\alpha=n/m\\\\), where \\\\(n\\\\) is the number of stored keys and \\\\(m\\\\) is the table capacity."],["Which algorithm is suitable for finding the inversion count of an array in \\\\(O(n\\log n)\\\\) time?",["Modified Merge Sort","Binary Search","Bubble Sort only","Linear Search"],0,"During merging, when an element from the right half is smaller than an element from the left half, it forms inversions with the remaining elements in the left half."],["Which sorting algorithm is generally considered in-place and has average-case \\\\(O(n\\log n)\\\\) complexity?",["Quick Sort","Radix Sort","Merge Sort","Counting Sort"],0,"Standard in-place Quick Sort partitions the array without creating a separate output array. Its average time is \\\\(O(n\\log n)\\\\)."],["Which search algorithm is appropriate for a sorted linked list?",["Interpolation Search","Linear Search","Jump Search with constant-time indexing","Binary Search with random access"],1,"Linked lists do not support efficient random access. Binary Search loses its usual advantage because reaching the middle requires traversal."],["What is the average-case time complexity of interpolation search on uniformly distributed sorted data?",["\\\\(O(n)\\\\)","\\\\(O(\\log n)\\\\)","\\\\(O(\\log\\log n)\\\\)","\\\\(O(1)\\\\)"],2,"For uniformly distributed data, interpolation search estimates the likely target position and achieves expected \\\\(O(\\log\\log n)\\\\) search time."],["What is the main advantage of Radix Sort?",["It requires a balanced BST.","It is always in-place.","It always uses comparisons to sort elements.","It can achieve linear-like performance by sorting digit positions."],3,"Radix Sort processes digits or characters using a stable intermediate sorting method. Its complexity depends on the number of digits and the digit range."],["Which condition is essential for using Binary Search correctly?",["The array must have an even number of elements.","The array must contain only positive integers.","The array must be sorted according to the search ordering.","The array must contain unique elements."],2,"Binary Search relies on ordering to eliminate half of the remaining search space. Duplicate elements are allowed."],["Which algorithm finds the shortest path in an unweighted graph?",["DFS","Prim's Algorithm","Kruskal's Algorithm","BFS"],3,"BFS explores vertices level by level. The first time a vertex is reached, its path has the minimum number of edges."],["Which algorithm is most appropriate for finding a minimum spanning tree in a connected, weighted, undirected graph?",["Dijkstra's Algorithm","Floyd-Warshall Algorithm","Bellman-Ford Algorithm","Kruskal's Algorithm"],3,"Kruskal's algorithm sorts edges by weight and adds edges that do not form a cycle, usually using Disjoint Set Union."],["Which algorithm can find shortest paths from a single source in a graph containing negative edge weights, provided there are no reachable negative-weight cycles?",["Prim's Algorithm","Bellman-Ford Algorithm","Dijkstra's Algorithm","BFS"],1,"Bellman-Ford repeatedly relaxes all edges and can handle negative weights. It also detects reachable negative-weight cycles."],["What is the time complexity of Floyd-Warshall's algorithm?",["\\\\(O(V^3)\\\\)","\\\\(O(V^2)\\\\)","\\\\(O(V+E)\\\\)","\\\\(O(E\\log V)\\\\)"],0,"It uses three nested loops over the vertices to compute all-pairs shortest paths."],["Which algorithm is used to detect a cycle in an undirected graph using Disjoint Set Union?",["Kruskal's approach","Binary Search","Insertion Sort","Floyd-Warshall"],0,"When processing an edge, if both endpoints already belong to the same set, adding that edge forms a cycle."],["A directed graph has a topological ordering if and only if it is:",["A complete graph","An undirected graph","Connected","A directed acyclic graph"],3,"Topological sorting is possible only for a DAG because a directed cycle creates contradictory ordering requirements."],["Which data structure is used by Kahn's algorithm for topological sorting?",["Max-Heap","Queue","Stack only","HashSet only"],1,"Kahn's algorithm places all zero-indegree vertices into a queue and processes them while updating neighboring indegrees."],["What is the time complexity of BFS using an adjacency list?",["\\\\(O(\\log V)\\\\)","\\\\(O(E^2)\\\\)","\\\\(O(V^2)\\\\)","\\\\(O(V+E)\\\\)"],3,"Every vertex is visited once, and every adjacency-list edge is examined once (or twice in an undirected graph, which remains \\\\(O(V+E)\\\\))."],["Which algorithm is generally suitable for finding a minimum spanning tree in a dense connected graph?",["Bellman-Ford","Prim's algorithm with an adjacency matrix","Binary Search","BFS only"],1,"Prim's algorithm with an adjacency matrix runs in \\\\(O(V^2)\\\\), which can be effective for dense graphs."],["What is the maximum number of edges in a simple undirected graph with \\\\(V\\\\) vertices?",["\\\\(2V\\\\)","\\\\(V(V-1)\\\\)","\\\\(V^2\\\\)","\\\\(\\frac{V(V-1)}{2}\\\\)"],3,"Every pair of distinct vertices can have at most one undirected edge. The number of pairs is \\\\(\\binom V2\\\\)."],["Which condition makes Dijkstra's algorithm unsuitable for guaranteeing shortest paths?",["The graph is connected.","The graph has positive-weight edges.","The graph contains cycles.","The graph has negative-weight edges."],3,"Dijkstra's greedy finalization assumes non-negative edge weights. Negative edges can improve an already finalized distance."],["What is the space complexity of an adjacency matrix representing a graph with \\\\(V\\\\) vertices?",["\\\\(O(V)\\\\)","\\\\(O(V+E)\\\\)","\\\\(O(V^2)\\\\)","\\\\(O(E)\\\\)"],2,"The matrix contains \\\\(V\\times V\\\\) entries, regardless of the actual number of edges."],["Which algorithm can detect whether an undirected graph is bipartite?",["Binary Search","Heap Sort","BFS using two-coloring","Dijkstra's algorithm"],2,"BFS assigns alternating colors to adjacent vertices. If two adjacent vertices receive the same color, the graph is not bipartite."],["What is the primary purpose of the Disjoint Set Union data structure?",["Maintaining connected components efficiently","Sorting arrays","Finding maximum subarrays","Finding shortest paths"],0,"DSU supports union and find operations, commonly optimized using path compression and union by rank or size."],["A connected undirected graph has \\\\(V\\\\) vertices and \\\\(V-1\\\\) edges. What can be concluded?",["It must contain a cycle.","It must be a complete graph.","It is a tree.","It must be disconnected."],2,"A connected undirected graph with exactly \\\\(V-1\\\\) edges is a tree and therefore contains no cycles."],["A graph contains negative-weight edges but no negative-weight cycles. Which algorithm can calculate shortest paths between every pair of vertices?",["BFS","Prim's Algorithm","Floyd-Warshall Algorithm","Kruskal's Algorithm"],2,"Floyd-Warshall supports negative edge weights and computes all-pairs shortest paths. It does not produce valid shortest paths when a negative cycle exists."],["Which technique is most suitable for efficiently finding the longest increasing subsequence (LIS) length in an array of \\\\(n\\\\) elements?",["Nested loops with \\\\(O(n^2)\\\\) complexity","Binary Search combined with a tails array","DFS traversal","Counting Sort"],1,"Maintain a tails array representing the smallest possible ending value for increasing subsequences of different lengths. Binary Search updates this array, achieving \\\\(O(n\\log n)\\\\) time."],["Which algorithm is most appropriate for finding strongly connected components in a directed graph?",["Binary Search","Kosaraju's Algorithm","Kruskal's Algorithm","Prim's Algorithm"],1,"Kosaraju's algorithm performs DFS, reverses the graph, and performs another DFS in a carefully determined finishing-time order. Its complexity is \\\\(O(V+E)\\\\)."],["What is the time complexity of finding the median of two sorted arrays of sizes \\\\(m\\\\) and \\\\(n\\\\), where the algorithm uses binary search on the smaller array?",["\\\\(O(\\log(\\min(m,n)))\\\\)","\\\\(O(m\\log n)\\\\)","\\\\(O(m+n)\\\\)","\\\\(O(\\log(m+n))\\\\)"],0,"Binary Search is performed on the smaller array to identify a correct partition between the two arrays. This gives \\\\(O(\\log(\\min(m,n)))\\\\) time."],["During DFS of an undirected graph, let u be the parent of v in the DFS tree. Which condition proves that tree edge (u, v) is a bridge?",["low[v] = disc[u]","low[v] > disc[u]","low[u] > disc[v]","low[v] \u003c disc[u]"],1,"If low[v] is greater than disc[u], no vertex in v's DFS subtree can reach u or an ancestor of u using a back edge. Removing (u, v) therefore disconnects that subtree."]].map(([q,o,a,e])=>({q,o,a,e,level:"Hard"}));

const dsaPlatformTestQs=[
{q:"What is the time complexity of accessing an element by index in an array?",o:["O(1)","O(log n)","O(n)","O(n log n)"],a:0,e:"Array elements occupy contiguous indexed positions, so calculating an element's address takes constant time."},
{q:"Which data structure follows the Last In, First Out (LIFO) principle?",o:["Queue","Stack","Binary search tree","Graph"],a:1,e:"A stack removes the most recently inserted element first, following LIFO order."},
{q:"Which operation inserts an element at the rear of a standard queue?",o:["Push","Pop","Enqueue","Peek"],a:2,e:"Enqueue adds an element at the rear of a queue; dequeue removes from the front."},
{q:"In a singly linked list, what does the next field of the last node normally contain?",o:["Address of the first node","Address of itself","A null reference","The list length"],a:2,e:"The final node has no successor, so its next reference is null."},
{q:"What is the time complexity of searching for a value in an unsorted singly linked list of n nodes?",o:["O(1)","O(log n)","O(n)","O(n log n)"],a:2,e:"In the worst case, every node must be examined, giving linear time."},
{q:"What is the base case in a recursive function?",o:["The call that always repeats","A condition that stops further recursive calls","The first variable declaration","A loop inside the function"],a:1,e:"A base case terminates recursion by returning without making another recursive call."},
{q:"A binary tree has at most how many children per node?",o:["One","Two","Three","Unlimited"],a:1,e:"A binary tree restricts each node to at most two children, commonly called left and right."},
{q:"Which traversal of a binary search tree visits keys in non-decreasing order?",o:["Preorder","Postorder","Inorder","Level order"],a:2,e:"Inorder traversal visits left subtree, node, then right subtree; this yields sorted order for a BST."},
{q:"Which condition is required for binary search to work correctly on an array?",o:["The array must be sorted","The array must contain unique values","The array length must be even","The array must contain positive values"],a:0,e:"Binary search eliminates half the remaining range based on order, so the search data must be sorted."},
{q:"What is the worst-case time complexity of binary search on a sorted array of n elements?",o:["O(1)","O(log n)","O(n)","O(n²)"],a:1,e:"Each comparison halves the remaining search interval, producing logarithmic worst-case time."},
{q:"Which sorting algorithm repeatedly compares adjacent elements and swaps them when they are out of order?",o:["Merge sort","Quick sort","Bubble sort","Selection sort"],a:2,e:"Bubble sort repeatedly compares adjacent elements and swaps inverted pairs during passes."},
{q:"What is the worst-case time complexity of merge sort on n elements?",o:["O(log n)","O(n)","O(n log n)","O(n²)"],a:2,e:"Merge sort divides the input into logarithmically many levels and performs linear total merging work per level."},
{q:"Which data structure is commonly used to implement a breadth-first search traversal?",o:["Stack","Queue","Heap","Hash table"],a:1,e:"BFS explores vertices in discovery order, so a FIFO queue holds the frontier."},
{q:"Which data structure is commonly used by an iterative depth-first search implementation?",o:["Queue","Stack","Priority queue","Circular array only"],a:1,e:"DFS explores a path deeply before backtracking; an explicit stack reproduces this behavior."},
{q:"In a hash table, what is a collision?",o:["Two keys produce the same table index","A key is deleted twice","The table is sorted","The table has no empty slots"],a:0,e:"A collision occurs when distinct keys map to the same hash-table index."},
{q:"Which technique resolves hash-table collisions by storing multiple entries in a bucket, often using a linked list?",o:["Linear probing","Separate chaining","Binary search","Heapifying"],a:1,e:"Separate chaining stores all entries that hash to the same bucket in a collection such as a linked list."},
{q:"What does Big-O notation primarily describe in algorithm analysis?",o:["Exact running time in seconds","An asymptotic upper bound on growth","The programming language used","The number of source-code lines"],a:1,e:"Big-O describes an asymptotic upper bound on how resource use grows with input size, ignoring constant factors."},
{q:"What is the time complexity of two nested loops that each execute n times, with constant work in the inner body?",o:["O(n)","O(log n)","O(n²)","O(2ⁿ)"],a:2,e:"The inner body executes n times for each of n outer iterations, for n × n = n² operations."},
{q:"Which algorithm design technique solves a problem by dividing it into smaller subproblems, solving them and combining their results?",o:["Greedy method","Divide and conquer","Backtracking only","Hashing"],a:1,e:"Divide and conquer divides the problem, solves subproblems (often recursively), then combines their results."},
{q:"In an unweighted graph, which traversal finds a path with the fewest edges from a source vertex to every reachable vertex?",o:["Depth-first search","Breadth-first search","Inorder traversal","Heap sort"],a:1,e:"BFS explores vertices in layers of increasing edge distance, so first discovery gives a minimum-edge path in an unweighted graph."},
{q:"Which data structure is commonly used to implement a breadth-first search frontier?",o:["Stack","Queue","Priority queue","Hash set"],a:1,e:"BFS uses a FIFO queue so vertices are processed in increasing distance from the source.",level:"Easy"},
{q:"Which traversal of a binary search tree visits keys in nondecreasing order?",o:["Preorder","Postorder","Inorder","Level order"],a:2,e:"Inorder traversal visits left subtree, node, then right subtree; for a BST this yields sorted order.",level:"Easy"},
{q:"Which data structure is used to evaluate a postfix expression?",o:["Queue","Stack","Graph","Heap"],a:1,e:"A stack stores operands; on an operator, the required operands are popped and the result pushed.",level:"Easy"},
{q:"Which sorting algorithm repeatedly selects the smallest remaining element and places it next?",o:["Insertion sort","Selection sort","Merge sort","Quick sort"],a:1,e:"Selection sort selects the minimum from the unsorted suffix and swaps it into the next position.",level:"Easy"},
{q:"Which graph representation stores a list of neighbours for each vertex?",o:["Adjacency matrix","Adjacency list","Incidence table only","Sorted array"],a:1,e:"An adjacency list stores the neighbours of each vertex and is space-efficient for sparse graphs.",level:"Easy"},
{q:"What is the worst-case time complexity of linear search in an array of n elements?",o:["O(1)","O(log n)","O(n)","O(n log n)"],a:2,e:"In the worst case linear search inspects every element.",level:"Easy"},
{q:"Which data structure is best suited for implementing undo operations?",o:["Stack","Queue","Min-heap","Trie"],a:0,e:"Undo commonly follows last-in-first-out behavior, which a stack supports naturally.",level:"Easy"},
{q:"In a min-heap, where is the minimum element stored?",o:["At the root","At the last leaf","At any random node","In the leftmost leaf always"],a:0,e:"The min-heap property guarantees that the root contains the smallest element.",level:"Easy"},
{q:"Which algorithm finds a minimum spanning tree by repeatedly choosing a light edge that joins different components?",o:["Dijkstra","Kruskal","Bellman-Ford","Floyd-Warshall"],a:1,e:"Kruskal sorts edges by weight and adds an edge when it connects two different components.",level:"Easy"},
{q:"Which data structure supports efficient prefix searches over strings?",o:["Trie","Stack","Binary heap","Disjoint set"],a:0,e:"A trie stores characters along paths and supports prefix-oriented lookup.",level:"Easy"},
{q:"What is the time complexity of inserting an element at the beginning of a singly linked list when the head is known?",o:["O(1)","O(log n)","O(n)","O(n log n)"],a:0,e:"The new node points to the current head and becomes the head, requiring constant work.",level:"Easy"},
{q:"Which condition is required for binary search to work correctly on a conventional array?",o:["Elements must be distinct","Elements must be sorted","Array length must be a power of two","Array must contain positive values"],a:1,e:"Binary search eliminates half the search interval based on ordering, so the data must be sorted.",level:"Easy"},
{q:"Which traversal visits a tree level by level?",o:["Inorder","Preorder","Postorder","Level order"],a:3,e:"Level-order traversal processes nodes breadth-first, usually using a queue.",level:"Easy"},
{q:"Which sorting algorithm is stable in its standard implementation and has O(n log n) worst-case time?",o:["Selection sort","Merge sort","Quick sort","Heap sort"],a:1,e:"Merge sort can preserve equal-key order when merging carefully and guarantees O(n log n) time.",level:"Easy"},
{q:"Which operation removes and returns the top item from a stack?",o:["Enqueue","Dequeue","Pop","Peek"],a:2,e:"Pop removes the top stack element; peek reads it without removing it.",level:"Easy"},
{q:"Which graph traversal is typically used to detect reachability from a starting vertex?",o:["DFS or BFS","Binary search","Heapify","Merge"],a:0,e:"DFS and BFS systematically explore reachable vertices from a source.",level:"Easy"},
{q:"What is the maximum number of children a binary tree node can have?",o:["1","2","3","Unlimited"],a:1,e:"A binary tree node has at most two children, conventionally called left and right.",level:"Easy"},
{q:"Which data structure is commonly used to implement recursion's function-call management?",o:["Call stack","Queue","Hash table","Min-heap"],a:0,e:"Each active function call has an activation record managed on the call stack.",level:"Easy"},
{q:"Which sorting algorithm is usually efficient for nearly sorted small arrays?",o:["Insertion sort","Heap sort","Counting sort","Radix sort"],a:0,e:"Insertion sort performs few shifts on nearly sorted data and has low overhead for small inputs.",level:"Easy"},
{q:"What does a hash collision mean?",o:["Two keys map to the same table index","A key is deleted twice","The table becomes sorted","A bucket has no elements"],a:0,e:"A collision occurs when distinct keys produce the same hash-table index.",level:"Easy"},
{q:"What is the worst-case time complexity of searching in an unbalanced binary search tree?",o:["O(1)","O(log n)","O(n)","O(n log n)"],a:2,e:"A highly skewed BST can behave like a linked list, requiring linear search time.",level:"Moderate"},
{q:"Which condition makes a binary search tree balanced in height?",o:["Every node has exactly two children","Its height remains O(log n)","All keys are positive","It has an even number of nodes"],a:1,e:"Height-balanced search trees maintain logarithmic height, enabling logarithmic search and update operations.",level:"Moderate"},
{q:"What is the auxiliary space complexity of recursive merge sort on an array?",o:["O(1)","O(log n)","O(n)","O(n squared)"],a:2,e:"Merging requires temporary storage proportional to n elements; recursion also uses a logarithmic call stack.",level:"Moderate"},
{q:"Why does Dijkstra's algorithm fail with negative-weight edges in general?",o:["It cannot process directed graphs","A finalized distance may later be improved by a negative edge","It requires an adjacency matrix","It only works on trees"],a:1,e:"Dijkstra's greedy finalization assumes extending a path cannot reduce its cost; negative edges violate that assumption.",level:"Moderate"},
{q:"Which algorithm can find shortest paths from one source when negative edges exist but no reachable negative cycle?",o:["Dijkstra","Bellman-Ford","Prim","Kruskal"],a:1,e:"Bellman-Ford relaxes all edges repeatedly and can detect reachable negative-weight cycles.",level:"Moderate"},
{q:"What is the amortized time complexity of appending to a dynamic array that doubles capacity when full?",o:["O(n)","O(log n)","O(1)","O(n log n)"],a:2,e:"Although an individual resize costs O(n), geometric growth makes the average cost per append O(1) amortized.",level:"Moderate"},
{q:"Which technique is used by union-find to make find operations very efficient?",o:["Path compression","Binary search","Topological sorting","Memoization"],a:0,e:"Path compression flattens trees during find; combined with union by rank/size it gives near-constant amortized operations.",level:"Moderate"},
{q:"A directed acyclic graph can be processed in which ordering so every edge goes from earlier to later?",o:["Inorder order","Topological order","Heap order","Lexicographic order only"],a:1,e:"A topological ordering of a DAG places each vertex before all vertices it points to.",level:"Moderate"},
{q:"What is the time complexity of building a binary heap from an arbitrary array using bottom-up heapify?",o:["O(n)","O(n log n)","O(log n)","O(n squared)"],a:0,e:"Bottom-up heap construction is O(n), because most nodes are near the leaves and require little sifting.",level:"Moderate"},
{q:"Which collision-resolution strategy stores multiple entries in a linked structure at each bucket?",o:["Linear probing","Quadratic probing","Separate chaining","Double hashing"],a:2,e:"Separate chaining keeps a collection of entries for each bucket index.",level:"Moderate"},
{q:"Which statement about a stable sorting algorithm is correct?",o:["It preserves the relative order of equal-key elements","It always uses O(1) memory","It is always faster","It sorts only integers"],a:0,e:"Stability means equal-key records retain their original relative order after sorting.",level:"Moderate"},
{q:"Which approach is appropriate for finding strongly connected components in a directed graph?",o:["Kosaraju's algorithm","Prim's algorithm","Binary insertion","Counting sort"],a:0,e:"Kosaraju's algorithm uses DFS passes on the graph and its transpose to identify strongly connected components.",level:"Moderate"},
{q:"What is the time complexity of BFS using an adjacency-list graph representation?",o:["O(V squared)","O(V+E)","O(E log V)","O(V log E)"],a:1,e:"BFS visits vertices and scans each adjacency list, giving O(V+E).",level:"Moderate"},
{q:"Which algorithm finds a minimum spanning tree by growing one tree from a start vertex using the cheapest crossing edge?",o:["Prim","Bellman-Ford","Floyd-Warshall","KMP"],a:0,e:"Prim's algorithm repeatedly adds the minimum-weight edge connecting the current tree to an outside vertex.",level:"Moderate"},
{q:"What is the main benefit of memoization in dynamic programming?",o:["It stores results of solved subproblems to avoid recomputation","It sorts input before processing","It eliminates all recursion","It reduces every problem to O(1)"],a:0,e:"Memoization caches subproblem results so repeated states are solved only once.",level:"Moderate"},
{q:"Which string-matching algorithm uses a prefix-function/LPS table to avoid rechecking matched characters?",o:["KMP","Dijkstra","Prim","Heap sort"],a:0,e:"Knuth-Morris-Pratt uses the longest proper prefix that is also a suffix to shift efficiently after mismatches.",level:"Moderate"},
{q:"What is the worst-case time complexity of quicksort with consistently poor pivot choices?",o:["O(n)","O(n log n)","O(n squared)","O(log n)"],a:2,e:"Highly unbalanced partitions lead to quadratic total work.",level:"Moderate"},
{q:"Which problem is a classic example of a greedy algorithm?",o:["Activity selection","All-pairs shortest paths with negative cycles","Matrix-chain multiplication","Longest common subsequence"],a:0,e:"Activity selection can be solved optimally by repeatedly choosing the compatible activity with earliest finish time.",level:"Moderate"},
{q:"What does a topological sort indicate if a directed graph has no valid topological ordering?",o:["It contains a directed cycle","It is disconnected","It has no edges","It has an even number of vertices"],a:0,e:"A directed graph has a topological ordering if and only if it is acyclic.",level:"Moderate"},
{q:"Which data structure supports extracting the next smallest item efficiently in a typical Dijkstra implementation?",o:["Min-priority queue","Stack","Deque only","Trie"],a:0,e:"A min-priority queue selects the unsettled vertex with the smallest tentative distance.",level:"Moderate"}
];

